INSERT INTO public.categories (id, name, slug, description, icon, image, sort_order, is_active, created_at, updated_at) VALUES ('e185b9c2-318b-4d72-9a24-7892a9890d7a', 'Party', 'party', 'Party games', 'PartyPopper', NULL, 7, true, '2026-06-26T16:50:57.830532+00:00', '2026-06-26T16:50:57.830532+00:00');
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-tetris', 'Gesture Tetris', 'Tilt your hand to guide falling blocks — no controller needed.', 'Classic Tetris reimagined for gesture control. All seven tetrominoes fall across a 10×20 grid, and your hand is the controller: tilt your wrist left or right to slide pieces, raise your hand to rotate clockwise, and push your hand down to soft-drop at 8× speed. A ghost piece shows exactly where your block will land, and satisfying Web Audio sound effects mark every move, rotate, lock, and line clear. Three difficulty levels set your starting speed — Easy begins at level 1, Normal at level 3, Hard at level 6. Score multiplies with your current level and sky-rockets on Tetris clears. All menus are navigated by hovering your hand and dwelling — no mouse or keyboard required.', 'Arcade', 'single', 1, 1, 'from-cyan-600 via-blue-600 to-violet-700', '#06b6d4', 4.6, 2026, 15, true, '2026-06-25T16:12:29.480197+00:00', '2026-06-25T16:33:30.899691+00:00', NULL, 'edaedab4-f74d-44b7-9569-33d388ea0a66', 'published', 'medium', '9-12', 'Classic Tetris fully controlled by hand gestures: tilt to move, raise to rotate, lower to drop fast.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/47b27359-fb1d-4ff9-a61e-24facff99080.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('bubble-shooter', 'Bubble Shooter', 'Aim with your finger, flick your wrist, pop bubbles with pure gesture control.', 'Point your index finger to aim the shooter and flick your wrist upward to launch a bubble. Match 3 or more same-colored bubbles to pop them. Popping clusters causes floating bubbles to fall for bonus points. Each level adds a new color and the grid keeps growing — how high can you score?', 'Puzzle', 'single', 1, 1, 'from-violet-600 via-purple-700 to-indigo-800', '#a855f7', 4.5, 2026, 10, false, '2026-06-25T11:53:10.935524+00:00', '2026-06-25T14:47:21.698371+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'easy', '9-12', 'Gesture-controlled bubble shooter — aim and flick to match colored bubbles.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/51fd958a-e0e6-4dba-9ce5-778f59f6754f.png', 2, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('simon-says-hands', 'Simon Says Hands', 'Remember the sequence. Slap the panels in order.', 'Four colored panels light up one by one — watch carefully, then reproduce the exact sequence by slapping each panel with a downward hand strike. Every round adds one more step. The sequence keeps growing and speeding up until you hit the wrong panel. Pure muscle memory meets pattern recognition, no controllers needed.', 'Puzzle', 'single', 1, 1, 'from-indigo-700 via-violet-700 to-blue-800', '#6366f1', 4.5, 2026, 8, false, '2026-06-24T16:42:24.281001+00:00', '2026-06-25T15:22:57.441581+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '9-12', 'Watch colored panels flash in sequence, then slap them in the same order with your hand.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/c87768a9-f002-4cfa-b81a-ef72b51c59e2.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('shield-hero', 'Shield Hero', 'Block with your hands. Survive the wave.', 'A gesture-controlled shield game where you move your hand to deflect incoming apples and stars. Play story mode across hand-crafted levels or go endless and chase the high score.', 'Action', 'single', 1, 1, 'from-blue-500 via-indigo-600 to-violet-700', '#6366f1', 4.5, 2025, 10, true, '2026-06-24T13:07:21.426837+00:00', '2026-06-25T15:28:41.722684+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '6-8', '', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/5f231eba-edef-4ced-baf5-5e918fb9736f.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('crossword-builder', 'Crossword Builder', 'Fill the grid, beat the clock.', 'A gesture-powered crossword where you pinch-and-drag to select letters. Solve themed puzzles across multiple difficulty levels using only your hands.', 'Puzzle', 'single', 1, 1, 'from-sky-500 via-blue-600 to-indigo-600', '#0ea5e9', 4.4, 2025, 15, false, '2026-06-23T19:08:12.947387+00:00', '2026-06-25T15:38:37.649181+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '6-8', '', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/eef59e66-fc4d-47d3-9144-6b365d5336d2.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-pong', 'Gesture Pong', 'Hand-tracked table tennis — beat the bot!', 'Control your paddle with just your hand. Move your index finger left and right to deflect the ball. Play Standard (first to 11) or Endless mode where the bot gets faster every point.', 'Sports', 'single', 1, 1, 'from-green-600 to-emerald-800', 'green', 4.5, 2025, 5, false, '2026-06-23T17:23:14.433625+00:00', '2026-06-25T15:57:51.459984+00:00', NULL, '311e4601-0ad4-41e9-9615-3521ed8df85b', 'published', 'medium', '9-12', 'Hand-tracked ping-pong — beat the AI or survive Endless mode.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/43cf45e5-8eb1-4646-9e7e-c4ecd658bffa.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('pizza-maker', 'Pizza Maker', 'Make the perfect pizza with your hands!', 'Use hand gestures to pick up and place ingredients on your pizza. Follow the order card exactly to score big — extra toppings cost you points. Bake and deliver for the highest accuracy score.', 'Arcade', 'single', 1, 1, 'from-orange-500 to-red-600', 'orange', 4.3, 2025, 5, false, '2026-06-23T17:23:14.433625+00:00', '2026-06-25T16:00:13.369497+00:00', NULL, 'edaedab4-f74d-44b7-9569-33d388ea0a66', 'published', 'easy', '13+', 'Gesture-controlled pizza making — follow the order and score big.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/9b129cdc-1b3b-4000-aa75-930049fedd68.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('cooking-chef', 'Cooking Chef', 'Cook with your hands — no utensils needed.', 'A gesture-controlled cooking adventure with 12 mini-games: flip pancakes, stack burgers, roll sushi, grill BBQ, decorate cakes, and more. Use hand gestures to prep, cook, and plate dishes before the timer runs out.', 'Arcade', 'single', 1, 1, 'from-orange-400 via-amber-500 to-yellow-500', '#f97316', 4.7, 2025, 20, true, '2026-06-22T14:22:31.199982+00:00', '2026-06-25T17:05:36.648202+00:00', NULL, 'edaedab4-f74d-44b7-9569-33d388ea0a66', 'published', 'medium', '6-8', 'Gesture-powered cooking minigames. Chop, flip and plate your way to glory!', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/3447fd3c-b969-4a15-8ee9-ee22df1b58b4.png', 21, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-runner', 'Gesture Runner', 'Run, jump, and slide through neon worlds!', 'A full-featured gesture-controlled runner with multiple characters, challenge modes, and a coin system. Jump with a raised hand, slide with a lowered hand — the longer you run, the higher your score.', 'Action', 'single', 1, 1, 'from-indigo-600 via-purple-600 to-pink-600', '#6366f1', 4.6, 2025, 15, true, '2026-06-22T14:22:31.199982+00:00', '2026-06-25T17:06:36.781014+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '9-12', 'Full-featured neon runner controlled entirely by hand gestures.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/92f3e536-2c3a-4753-94d7-a65aed3ac1a1.png', 7, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('connect-4', 'Connect 4 — Gesture Edition', 'Drop, block, and connect four to win.', 'The timeless Connect 4 strategy game, played with hand gestures. Point to choose a column, then drop your disc. First to four in a row wins.', 'Puzzle', 'both', 1, 2, 'from-red-500 via-amber-500 to-blue-700', '#ef4444', 4.4, 2025, 8, false, '2026-06-29T11:49:25.253561+00:00', '2026-07-02T11:25:49.128093+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '6-8', '', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/effe4b41-dce9-467f-a00f-de13c902e123.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('air-hockey', 'Hand Air Hockey', 'Flick, block, and score with bare hands.', 'A fast-paced air hockey game controlled entirely by hand gestures. Move your paddle with your open hand, score goals, and challenge a friend or the AI.', 'Sports', 'both', 1, 2, 'from-cyan-400 via-blue-500 to-violet-600', '#06b6d4', 4.5, 2025, 10, false, '2026-06-29T11:49:25.253561+00:00', '2026-07-02T11:28:39.448055+00:00', NULL, '311e4601-0ad4-41e9-9615-3521ed8df85b', 'published', 'medium', '6-8', '', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/e880d8cf-a648-4fae-b17b-654cd087643f.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('tic-tac-toe', 'Gesture Tic Tac Toe', 'X vs O — no hands, just gestures.', 'Classic Tic Tac Toe reimagined with hand tracking. Point your finger to place your mark. Supports 1-player (vs AI) and 2-player local modes.', 'Puzzle', 'both', 1, 2, 'from-rose-500 via-fuchsia-600 to-violet-700', '#c026d3', 4.3, 2025, 5, false, '2026-06-29T11:49:25.253561+00:00', '2026-07-02T11:26:36.971988+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '6-8', '', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/228d97ea-5a04-47e7-b5e8-910e2d8633dc.png', 2, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-word', 'GestureWords', 'Spell it out — letter by letter in the air.', 'A gesture-powered word game where you hover over letters to build words. Race against the clock, climb difficulty tiers, and beat your high score.', 'Puzzle', 'single', 1, 1, 'from-violet-500 via-indigo-600 to-teal-600', '#7c6af7', 4.6, 2025, 12, false, '2026-06-29T11:49:25.253561+00:00', '2026-07-02T11:27:21.487726+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '6-8', '', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/8cb001db-d717-4fd6-b5d0-5deb1f81cf25.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-piano', 'Gesture Piano', 'Play piano with your fingertips — no keys required.', 'A Guitar Hero–style music game mapped to a 10-key virtual piano (C4–E5). Hover your fingertips over the colored key zones to play notes. In Rhythm mode, colored bars fall from the top of the screen — catch each bar with the matching finger when it reaches the hit line to score. Three built-in songs span all skill levels: Easy (Twinkle Twinkle, 80 BPM), Medium (Ode to Joy, 100 BPM), and Hard (Für Elise–inspired, 120 BPM with rapid runs). Free Play lets you explore the piano freely without any timing pressure. Perfect for practicing finger coordination and extending the music genre beyond just drums.', 'Arcade', 'single', 1, 1, 'from-purple-600 via-violet-600 to-indigo-700', '#8b5cf6', 4.5, 2026, 10, true, '2026-06-25T13:33:34.215816+00:00', '2026-06-25T14:39:24.085739+00:00', NULL, 'edaedab4-f74d-44b7-9569-33d388ea0a66', 'published', 'medium', '6-8', 'Guitar Hero–style piano: catch falling bars with your fingertips to play real piano notes.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/43968884-b036-4311-864b-f810ae66d1bd.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-drums', 'Gesture Drums', 'Air-drum a full kit with your bare hands.', 'Hit eight virtual drum pads by striking the air over them. Your left hand controls Hi-Hat, Crash, Snare, and Rim Shot; your right hand controls Kick, Tom, Floor Tom, and Cowbell. Free Play mode lets you jam freely, while Rhythm Challenge drops three songs at 80, 110, and 140 BPM — hit the falling note bars in time to rack up combos and accuracy bonuses. Pure Web Audio synthesis means zero downloads: every drum sound is generated live in the browser.', 'Action', 'single', 1, 1, 'from-purple-700 via-violet-700 to-indigo-800', '#a855f7', 4.5, 2026, 10, false, '2026-06-24T14:34:38.885688+00:00', '2026-06-25T15:26:37.697741+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '9-12', 'Air-drum a full 8-pad kit using hand gestures and beat your own rhythm score.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/008513f9-ec18-46f3-9f60-af6efcc8e898.png', 6, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('flags-game', 'Flags Quiz', 'Test your world flags knowledge with your hands!', 'Point and gesture to identify flags from around the world. Play Campaign mode to progress through continents, Arcade for free play, or Survival for an endless challenge with 3 lives.', 'Puzzle', 'single', 1, 1, 'from-blue-600 to-indigo-800', 'blue', 4.4, 2025, 5, false, '2026-06-23T17:33:10.575299+00:00', '2026-06-25T15:43:54.665578+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '13+', 'Hand-gesture flags quiz — Campaign, Arcade, or Survival mode.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/6dc24349-9771-4c36-8d54-2f3d170a1fb3.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('green-red-light', 'Green Red Light', 'Freeze when the light turns red!', 'Move your body during green light to score points, but freeze perfectly still when it switches to red. Get caught moving on red and you are eliminated. Survive all rounds to win!', 'Action', 'single', 1, 1, 'from-green-500 to-red-600', 'green', 4.6, 2025, 3, false, '2026-06-23T17:33:10.575299+00:00', '2026-06-25T15:45:36.139756+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '13+', 'Move on green, freeze on red — body-tracking reaction game.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/170a067d-564f-4b49-be4d-5d564c432d8e.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('monster-dodge', 'Monster Dodge', 'Dodge the monsters — how long can you survive?', 'Monsters are coming from all directions and only your reflexes can save you. Use gestures to move your character and avoid being caught. Survive as long as possible!', 'Action', 'single', 1, 1, 'from-red-700 via-orange-600 to-yellow-500', '#ef4444', 4.1, 2025, 8, false, '2026-06-22T14:22:31.199982+00:00', '2026-06-26T13:28:09.916668+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '6-8', 'Dodge incoming monsters using your body. Survive as long as you can!', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/4da39af0-089b-474e-b51e-8bcaef46967f.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('mirror-me', 'Mirror Me', 'Strike the pose — mirror every gesture!', 'Copy the poses shown on screen using your body. The faster and more accurately you mirror each pose, the higher your score. Chain combos for massive bonus multipliers.', 'Action', 'single', 1, 1, 'from-purple-600 to-pink-500', 'purple', 4.5, 2025, 5, false, '2026-06-23T17:33:10.575299+00:00', '2026-06-25T15:47:00.214612+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '9-12', 'Mirror poses with your body for speed and accuracy combos.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/ea2730bb-961d-4ce8-b171-c61feb5c1738.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('butterfly-catch', 'Butterfly Catch', 'Chase and catch fluttering butterflies!', 'Use your hands to catch colorful butterflies as they flutter across the screen. A calm and beautiful gesture game perfect for young kids.', 'Action', 'single', 1, 1, 'from-lime-400 to-emerald-400', '#84cc16', 4.4, 2025, 8, false, '2026-06-23T13:38:42.118483+00:00', '2026-06-25T16:39:40.860449+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'easy', '3-5', 'Catch butterflies with hand gestures.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/cb2ef27e-2077-44eb-8fda-21d33b111755.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-space-shooter', 'Space Shooter', 'Defend the galaxy with your hands!', 'Aim and fire at enemy spaceships using hand gesture controls. Dodge incoming attacks and survive as long as possible in deep space.', 'Action', 'single', 1, 1, 'from-slate-700 to-indigo-600', '#4f46e5', 4.4, 2025, 10, false, '2026-06-23T13:38:42.118483+00:00', '2026-06-25T17:01:28.950322+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '9-12', 'Gesture-controlled space shooter game.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/6d08cc0c-6f63-4d6b-8ff5-c32aca008bcf.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('balloon-pop-adventure', 'Balloon Pop Adventure', 'Pop every balloon before time runs out!', 'Use hand gestures to pop colorful balloons as they float across the screen. Race against the clock in single or two-player mode and aim for the highest score.', 'Action', 'both', 1, 2, 'from-pink-500 via-rose-500 to-orange-500', '#f43f5e', 4.3, 2025, 8, true, '2026-06-22T14:22:31.199982+00:00', '2026-06-23T16:26:00.58586+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'easy', '3-5', 'Pop balloons with hand gestures — solo or with a friend!', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/18af1aa3-ed2d-43e1-a582-ba2fb45b683e.png', 7, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('circuit-racer', 'Circuit Racer', 'Multi-lap racing with gesture controls and AI opponents.', 'Circuit Racer is a gesture-controlled racing sim and the thirteenth game in the KinetoFun family — the first racing game and a direct successor to the persistent-sim infrastructure proven by both Little Farm Builder (ADR-045) and Pocket Pal (ADR-046). Unlike Farm Builder''s coin-grinding or Pocket Pal''s pet care, Circuit Racer delivers genuine gameplay progression: 6 hand-authored racing courses with escalating AI difficulty (easy → hard), linear unlock via top-3 finishes (matching the-sniper-code''s mission-progression pattern), and lap-based scoring. Player controls a car with gesture inputs (hand-X steers, raise hand accelerates, lower hand brakes, fist boost). Three AI opponents race simultaneously on every course; position at finish (1st/2nd/3rd/4th+) determines coins earned (3/2/1/0 respectively). Lap tracking detects crossings via finish-line hit zones; race ends when the first car completes all laps for that course (3–5 lap counts vary by difficulty). No fail state: player always scores based on final position, no DNF penalties. Vehicle physics fork Matter.js suspension from gesture-hill-adventure with steering added (hand-X applies angular velocity to chassis). Behind-the-car perspective rendering reuses trapezoid projection + camera system verbatim from gesture-mob-rally (depth-sort painter''s algorithm, 4 entities = player + 3 AI cars). Lap tracker is new (determines race completion, lap times, position ordering). AI racers use simple waypoint-following with speed modifiers per difficulty. Course progression matches sniper-code''s locked/unlocked unlock pattern: beat course N in top 3 to unlock course N+1 (linear chain, c1 → c6). Star rating: 1st = 3 stars, 2nd = 2 stars, 3rd = 1 star; stars persist and are re-earned if player beats prior best. Score submitted on exit is lifetime total coins earned (monotonic), so leaderboards show max coins across all races (same shape as farm-builder / pocket-pal, generic `public.scores` table). No new DB schema, no per-game races table. 6 achievements planned (First Race, Lap Master, Course King, Perfect Run, 100-Coin Champion, All Courses Unlocked). Reuses single shared MediaPipe HandLandmarker session, Web Audio synthesis for SFX, Zustand persist for progress (localStorage ''circuit-racer-progress''). Built Vite game served from `public/games/circuit-racer/`. Pending: full AI pathfinding refinement, real track geometry (procedural or hand-drawn), visual polish (environments, HUD graphics). Steering mechanics (0.08 rad/s at max, speed-sensitive) is untested in live camera environment.', 'Sports', 'single', 1, 1, 'from-blue-900 via-purple-900 to-indigo-900', '#00D4FF', 4.7, 2026, 0, true, '2026-07-03T12:25:47.419346+00:00', '2026-07-07T13:11:31.589998+00:00', NULL, '311e4601-0ad4-41e9-9615-3521ed8df85b', 'published', 'medium', '9-12', 'Fast-paced multi-lap racing with AI opponents and progressive difficulty — gesture-controlled high-speed action.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/ee47e418-cba5-47b5-932f-9349f2fd8778.png', 8, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('happy-glass', 'Happy Glass', 'Draw the path — fill the glass!', 'A physics-based drawing puzzle. Draw lines and curves to guide water droplets into a glass. 20 increasingly tricky levels test your creativity and spatial thinking.', 'Puzzle', 'single', 1, 1, 'from-blue-500 via-cyan-500 to-sky-400', '#3b82f6', 4.7, 2025, 20, true, '2026-06-22T14:22:31.199982+00:00', '2026-06-29T10:39:26.440107+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '6-8', 'Draw paths to guide water into the glass. 20 physics puzzles await!', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/f36e8dc7-0ec1-4a3c-a94b-119a6fed9683.png', 8, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('weather-seasons-sorter', 'Weather & Seasons Sorter', 'Point at the right outfit for the weather — sun, snow, rain, and wind, both directions.', 'Weather & Seasons Sorter is a gesture-only game that teaches kids weather and season reasoning, built on the same proven hover-select platform as Clock & Time Teller and Coin & Money Counter. Each round shows a weather/season scenario one of two ways — a weather-scene icon or a matching clothing/activity icon — and the player hovers a fingertip over the matching answer among a few choices (~600ms dwell) to score. Two modes teach the reasoning from both directions: What to Wear (see the weather, pick the right clothing) and Match the Weather (see the clothing, pick the right weather), plus a Mixed mode that quizzes both ways. Eight weather/season scenarios (sunny summer, snowy winter, rainy spring, windy fall, hot desert day, foggy morning, stormy day, cloudy afternoon), each with one canonical correct clothing/activity answer, so wrong choices are always plausible-looking but genuinely different items rather than near-duplicates. Optional spoken narration says each scenario with a short description ("Sunny Summer — wear your sunhat!"). Same no-penalty philosophy as every other KinetoFun gesture game: wrong answers just wobble with a soft tone, no score deduction, no fail state, every session earns at least one star. 6 achievements (First Round, Weather Watcher Master, Clothing Expert Master, Mixed Master, Perfect Round, Season Sage). Reuses the same proven gesture stack as the sibling games — single shared MediaPipe HandLandmarker session, hover-dwell selection, Web Audio synthesis + Web Speech narration, Zustand persisted local save. No per-game scores table needed — same generic `public.scores` wiring as every other game.', 'Puzzle', 'single', 1, 1, 'from-sky-950 via-blue-900 to-indigo-950', '#4A90D9', 4.7, 2026, 6, true, '2026-07-02T13:05:52.072964+00:00', '2026-07-02T13:25:45.379704+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'easy', '3-5', 'Gesture-only weather-matching game: point at the right outfit for the weather — no fail state, ever.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/918d1de2-cebc-43cb-ae07-902dec8859f7.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('color-artist-gesture-quest', 'Color Artist: Gesture Quest', 'Paint the world with your hands!', 'A creative gesture-based painting game powered by MediaPipe hand tracking. Choose colors and brushes by holding gestures, then draw freely on the canvas. Complete world-themed drawing quests to unlock new tools.', 'Adventure', 'single', 1, 1, 'from-violet-500 via-purple-500 to-fuchsia-500', '#7c3aed', 4.5, 2025, 20, false, '2026-06-22T14:22:31.199982+00:00', '2026-06-25T17:11:46.851839+00:00', NULL, '85e61bd0-7140-4540-bdaf-b5e6ed2e6b63', 'published', 'easy', '6-8', 'Use hand gestures to paint, draw and complete creative quests!', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/6252f2d1-c6a1-4347-aced-ab01a5bbf0c8.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-road-builder', 'Gesture Road Builder', 'Build roads with your hands and guide the car home!', 'Use hand gestures to place road tiles and create a path for the car to reach its destination. Each level adds new obstacles and tighter spaces to plan through.', 'Puzzle', 'single', 1, 1, 'from-amber-500 via-yellow-500 to-lime-500', '#eab308', 4, 2025, 15, false, '2026-06-22T14:22:31.199982+00:00', '2026-06-26T13:20:59.125377+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '9-12', 'Place road tiles with gestures to guide the car to safety.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/85f65bde-9866-430b-bc31-a6c36c9f1905.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('air-painting', 'Air Painting', 'Your hand is the paintbrush!', 'Draw freely in the air using hand tracking. Express your creativity with colors, shapes, and strokes detected by your camera.', 'Puzzle', 'single', 1, 1, 'from-fuchsia-500 to-pink-400', '#a855f7', 4.1, 2025, 10, false, '2026-06-23T13:38:42.118483+00:00', '2026-06-26T11:45:45.58956+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'easy', '6-8', 'Free-form gesture painting canvas.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/36fa6a20-2f86-406a-ae96-1eb107647b31.png', 4, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-math-adventure', 'Gesture Math Adventure', 'Solve problems with your hands — math has never been this fun!', 'Answer maths questions by holding up the right number of fingers or making the correct gesture. Covers addition, subtraction and multiplication. Great for building number fluency.', 'Puzzle', 'single', 1, 1, 'from-violet-600 via-purple-500 to-indigo-500', '#8b5cf6', 4.3, 2025, 12, false, '2026-06-22T14:22:31.199982+00:00', '2026-06-26T13:18:05.031221+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'easy', '9-12', 'Answer maths questions using hand gestures. Learning through play!', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/cdaa23ad-543c-463f-8396-618a9e7acc38.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('goalkeeper-hero', 'Goalkeeper Hero', 'Dive and save — can you stop every shot?', 'Step into goal and use your body to block incoming shots. Raise your left or right hand to dive in that direction. The shots get faster and more unpredictable as you progress.', 'Sports', 'single', 1, 1, 'from-green-500 via-emerald-600 to-teal-700', '#22c55e', 4.2, 2025, 10, false, '2026-06-22T14:22:31.199982+00:00', '2026-06-26T13:24:31.613966+00:00', NULL, '311e4601-0ad4-41e9-9615-3521ed8df85b', 'published', 'easy', '6-8', 'Use body gestures to block shots and become the ultimate goalkeeper!', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/8cc9264c-79de-4357-8e7e-bbe3aa31a9b1.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('language-adventure', 'Language Adventure', 'Explore new words on an epic journey!', 'Embark on a language-learning adventure where you unlock new vocabulary by completing gesture-based challenges. Match words to images, spell with fingers, and earn badges for each world you complete.', 'Adventure', 'single', 1, 1, 'from-sky-500 via-blue-500 to-indigo-600', '#0ea5e9', 4.3, 2025, 20, false, '2026-06-22T14:22:31.199982+00:00', '2026-06-26T13:25:37.739933+00:00', NULL, '85e61bd0-7140-4540-bdaf-b5e6ed2e6b63', 'published', 'easy', '6-8', 'Learn new words through gesture challenges on an epic quest!', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/20a80407-6622-44c3-9062-b8b1a58af64b.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('block-blast-gesture', 'Block Blast', 'Blast blocks with your bare hands!', 'Swipe and gesture to blast falling blocks before they stack up. A fast-paced puzzle game powered by hand gesture detection.', 'Puzzle', 'single', 1, 1, 'from-orange-500 to-red-500', '#f97316', 4.3, 2025, 8, false, '2026-06-23T13:38:42.118483+00:00', '2026-06-25T16:32:12.384649+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '6-8', 'Gesture-controlled block blasting game.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/8dbc5ec1-cbc9-4294-9cef-c838e684f0be.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('mouth-open-catch', 'Mouth Open Catch', 'Open wide and catch everything that falls!', 'Your face is the controller! Open your mouth to catch falling fruits and close it to avoid bombs. Uses your webcam to detect mouth movements in real time. A hilarious and unique experience.', 'Action', 'single', 1, 1, 'from-yellow-400 via-orange-400 to-red-500', '#f97316', 4.4, 2025, 8, true, '2026-06-22T14:22:31.199982+00:00', '2026-06-25T17:09:19.363956+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'easy', '3-5', 'Open your mouth to catch falling objects! Powered by face detection.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/a2b2d7bb-bbe1-4bf1-8403-ec91f84a7bbd.png', 2, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('block-breaker', 'Block Breaker', 'Smash every brick with precision.', 'Classic brick-breaker reimagined with hand gesture controls. Angle your paddle with your hand, launch power-ups, and clear the board before time runs out.', 'Arcade', 'single', 1, 1, 'from-orange-500 via-red-500 to-rose-600', '#f97316', 4.3, 2025, 8, false, '2026-06-23T19:08:12.947387+00:00', '2026-06-25T15:36:42.039643+00:00', NULL, 'edaedab4-f74d-44b7-9569-33d388ea0a66', 'published', 'medium', '6-8', '', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/d4fbf365-a421-481e-ac2a-7c3219793129.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('air-coloring-book', 'Air Coloring Book', 'Color with the wave of a hand!', 'Use hand gestures to pick colors and fill a digital coloring book. No brush needed — just point and paint in the air.', 'Puzzle', 'single', 1, 1, 'from-pink-400 to-purple-500', '#ec4899', 4.2, 2025, 10, false, '2026-06-23T13:38:42.118483+00:00', '2026-06-26T11:34:10.198397+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'easy', '3-5', 'Gesture-powered coloring book.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/8b204390-9f98-4890-9bc2-e72fd891a6c9.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-love-balls', 'Gesture Love Balls', 'Draw paths with your hand to reunite two lovesick balls.', 'Gesture Love Balls is a gesture-powered physics puzzle game inspired by Love Balls. Two balls — one blue, one pink — are separated across each level by walls, platforms, and devious obstacles. Your mission is to bring them together by drawing lines and shapes using only your hand movements. Pinch your thumb and index finger together and move your hand to draw a line in mid-air. When you release the pinch, the line solidifies into a rigid physics object that the balls can roll down, bounce off, or slide along. Guide them to touch and watch the hearts fly! Features 30 handcrafted levels with increasing complexity — from simple bridges across a gap to multi-obstacle gauntlets with moving platforms, rotating beams, and deadly spikes. An ink meter limits each drawing session, rewarding elegant solutions with up to 3 stars. All menus and in-game controls work entirely through gesture: hover your hand cursor over any button for one second to activate it. Make a fist to reset your drawings. No keyboard, no mouse — pure gesture-based play. Progress, star ratings, and best scores are saved locally.', 'Puzzle', 'single', 1, 1, 'from-purple-600 via-pink-500 to-purple-800', '#a855f7', 4.7, 2026, 15, false, '2026-06-26T16:02:24.982857+00:00', '2026-06-26T19:17:25.381171+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'draft', 'easy', '9-12', 'Draw lines with your hand to connect the two lovesick balls — 30 gesture-only physics puzzles.', NULL, 10, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-hill-adventure', 'Gesture Hill Adventure', 'Raise your hand to drive, lower it to brake, and conquer endless procedural hills.', 'Gesture Hill Adventure is a physics-based hill-climb racing game controlled entirely by your hand — no keyboard, mouse, or controller needed. Raise your open hand to hit the throttle and send your cartoon buggy climbing over steep procedural hills; lower it to brake before the next drop; and make a fist for a short turbo boost to launch off ramps and nail big air. Your buggy is powered by a real physics engine with suspension springs, weighted chassis, and freely spinning wheels, so every hill crests differently and landings carry real momentum. Drive through six gorgeous environments that rotate automatically as you push further — lush Forest, scorching Desert, icy Snow, fiery Volcano, low-gravity Moon, and the surreal Candy World — each with its own parallax sky, terrain palette, ambient particles (snowflakes, lava sparks, candy confetti), and sound atmosphere. Perform backflips, frontflips, and double flips to earn stunt bonuses and build a combo multiplier. Nail a perfect landing (gentle touchdown) for extra points. Fly high enough to trigger a Big Jump bonus, or stay airborne for an Air Time streak. Combo chains are displayed on canvas in real time — let the timer run out and the multiplier resets. Collect spinning gold coins and glowing fuel canisters scattered across the hills. Managing your fuel gauge is critical: it drains while driving and boosts drain it faster — pick up canisters to keep going. Run dry or flip upside-down too long and it''s game over. Six unlockable vehicle skins are available in the Garage — earn coins in-game to purchase the Monster Crusher, Beach Cruiser, Patrol Cruiser, Space Rover, and Neon Racer. Every menu screen is gesture-driven: hover your cursor over a button for one second to activate it, giving you full hands-free navigation. Statistics, best distance, high scores, coins, unlocked skins, and settings are all saved locally between sessions.', 'Adventure', 'single', 1, 1, 'from-green-900 via-emerald-900 to-teal-950', '#10b981', 5, 2026, 10, true, '2026-06-30T12:22:47.262411+00:00', '2026-07-03T10:18:48.904796+00:00', NULL, '85e61bd0-7140-4540-bdaf-b5e6ed2e6b63', 'published', 'medium', '9-12', 'Physics hill-climb racer: raise hand to throttle, lower to brake, fist to boost. Flip stunts, 6 environments, garage skins.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/c10a6987-762c-45c9-88fc-2d2c0c8310f2.png', 8, 1);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-air-hockey', 'Gesture Air Hockey', 'Slap the puck, win the table.', 'Air hockey controlled entirely by hand gestures. Move your paddle by waving, block shots, and score goals in this fast-paced two-player showdown.', 'Sports', 'multi', 2, 2, 'from-cyan-400 via-teal-500 to-emerald-600', '#06b6d4', 4.5, 2025, 10, true, '2026-06-23T19:08:12.947387+00:00', '2026-06-25T15:30:14.597204+00:00', NULL, '311e4601-0ad4-41e9-9615-3521ed8df85b', 'published', 'medium', '6-8', '', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/c760ed64-9973-4cab-ad9d-49b82e3d2cdb.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('neon-flow', 'Neon Flow', 'Connect the dots, light the grid.', 'A neon flow-connection puzzle game with hand tracking. Pinch and drag glowing lines to connect matching colored dots and fill every cell of the grid.', 'Puzzle', 'single', 1, 1, 'from-fuchsia-500 via-pink-500 to-rose-500', '#d946ef', 4.6, 2025, 12, true, '2026-06-23T19:08:12.947387+00:00', '2026-06-25T15:32:27.180745+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '6-8', '', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/c99c61d5-7f2e-4db2-86cf-888cff05ed70.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('mix-it-up', 'Mix It Up', 'Stir your way to a reaction.', 'A chemistry-themed gesture game where you wave your hand to mix colorful liquids. Combine the right elements before time runs out or things get explosive.', 'Puzzle', 'single', 1, 1, 'from-violet-500 via-purple-600 to-fuchsia-600', '#8b5cf6', 4.2, 2025, 6, false, '2026-06-23T19:08:12.947387+00:00', '2026-06-25T15:39:45.210076+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '6-8', '', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/9326d2fd-554a-43ce-a65b-f0cb33677881.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('block-blast-gestures', 'Block Blast Pro', 'More blocks, more blasting!', 'An upgraded block blasting experience — swipe gestures to destroy rows and columns before the board fills up. Beat your high score!', 'Puzzle', 'single', 1, 1, 'from-red-500 to-orange-400', '#ef4444', 4.2, 2025, 8, false, '2026-06-23T13:38:42.118483+00:00', '2026-06-25T16:30:56.799901+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '9-12', 'Advanced gesture block puzzle game.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/dc4c168d-47ed-498b-bef7-92118649ddc3.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-brickbreaker', 'Brick Breaker', 'Smash bricks with a wave!', 'Move your hand to control the paddle and bounce the ball to smash all the bricks. A gesture-powered take on the classic Breakout game.', 'Arcade', 'single', 1, 1, 'from-violet-600 to-purple-500', '#7c3aed', 4.3, 2025, 10, false, '2026-06-23T13:38:42.118483+00:00', '2026-06-25T16:38:21.259609+00:00', NULL, 'edaedab4-f74d-44b7-9569-33d388ea0a66', 'published', 'medium', '6-8', 'Classic brick breaker with gesture controls.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/69735491-3500-4b1e-a140-bdd14f062a20.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('fish-catcher', 'Fish Catcher', 'Cast your hands and reel them in!', 'Swipe your hand like a net to catch fish swimming across the screen. A relaxing but challenging gesture game for all ages.', 'Action', 'single', 1, 1, 'from-cyan-500 to-blue-400', '#06b6d4', 4.2, 2025, 10, false, '2026-06-23T13:38:42.118483+00:00', '2026-06-25T16:40:51.960092+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'easy', '3-5', 'Catch fish using hand gestures.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/46355393-512b-4f20-9a67-18213837a212.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('handcell-game', 'Hand Cell', 'Control cells with your hands!', 'Guide microscopic cells through challenges using hand gestures. A unique and educational gesture game that makes biology fun.', 'Adventure', 'single', 1, 1, 'from-teal-500 to-cyan-400', '#14b8a6', 4, 2025, 10, false, '2026-06-23T13:38:42.118483+00:00', '2026-06-25T16:45:56.401373+00:00', NULL, '85e61bd0-7140-4540-bdaf-b5e6ed2e6b63', 'published', 'medium', '9-12', 'Guide cells using hand gesture controls.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/7fb6524f-8d5f-4e92-b006-7eb6937b122c.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('knife-hit-gesture', 'Knife Hit', 'Throw knives with a flick of the wrist!', 'Flick your hand to throw knives at a spinning wooden target. Time your throws carefully to avoid hitting other knives. Gesture-powered fun!', 'Action', 'single', 1, 1, 'from-stone-600 to-amber-700', '#78716c', 4.3, 2025, 8, false, '2026-06-23T13:38:42.118483+00:00', '2026-06-25T16:49:38.464222+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '9-12', 'Flick your wrist to throw knives.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/0794a59c-5884-4d15-b455-8e4cd27087fe.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('ninja-star-throw', 'Ninja Star Throw', 'Throw like a true ninja warrior!', 'Flick your wrist to throw ninja stars at targets. Earn points for accuracy and speed as the targets move faster with each level.', 'Action', 'single', 1, 1, 'from-gray-800 to-slate-600', '#374151', 4.4, 2025, 8, false, '2026-06-23T13:38:42.118483+00:00', '2026-06-25T16:53:38.256068+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '9-12', 'Throw ninja stars with wrist gestures.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/08df9c16-3f16-4874-b86e-6ee974b84f0b.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('space-defender', 'Space Defender', 'Protect Earth from alien invaders!', 'Use hand gestures to aim and fire at waves of alien spaceships attacking Earth. How many waves can you survive before your shields fail?', 'Action', 'single', 1, 1, 'from-blue-900 to-indigo-700', '#1e3a8a', 4.3, 2025, 10, false, '2026-06-23T13:38:42.118483+00:00', '2026-06-25T17:00:36.526934+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '9-12', 'Defend Earth with gesture-powered weapons.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/71a54ea8-b5d3-428a-8dfe-383bb88e77d5.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('traffic-controller', 'Traffic Controller', 'Direct traffic with your bare hands. No crashes on your watch.', 'You are the cop at a busy 4-way intersection. Cars queue from all directions — point right to open the North-South lane, point left for East-West, wave to let pedestrians cross, and palm-stop to freeze everything. Each green phase lasts 7 seconds then resets, so you must stay active. Cars left waiting too long run the red light — three of those and it is chaos. Difficulty scales every minute as spawn rates increase.', 'Adventure', 'single', 1, 1, 'from-amber-700 via-orange-700 to-yellow-800', '#f59e0b', 4.5, 2026, 10, false, '2026-06-24T17:10:28.486623+00:00', '2026-06-25T14:49:42.238166+00:00', NULL, '85e61bd0-7140-4540-bdaf-b5e6ed2e6b63', 'published', 'hard', '9-12', 'Direct cars at a 4-way intersection using hand gestures — point, wave, and stop traffic before it overflows.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/7693ddc6-60d0-44c6-808e-3c4928b587f1.png', 3, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('slingshot-bird', 'Slingshot Bird', 'Pinch, pull, and launch to destroy pig fortresses.', 'Use your hand like a real slingshot — pinch your thumb and index finger near the bird, pull back, and release to launch it at pig-filled structures. Wood, glass, and stone blocks defend the pigs at increasing difficulty across 4 handcrafted levels. Trajectory dots help you aim, and unused birds earn bonus points. Completely gesture-controlled with dwell-to-select menus.', 'Action', 'single', 1, 1, 'from-red-500 via-orange-500 to-yellow-500', '#ef4444', 4.6, 2026, 10, false, '2026-06-24T16:03:51.322891+00:00', '2026-06-25T15:24:23.547369+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'easy', '13+', 'Pinch and fling a bird to smash pig fortresses across 4 levels.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/b8b08386-21f9-46d2-a1b6-41536349f8e7.png', 7, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('samurai-slice', 'Samurai Slice', 'Slice fast. Honor the code.', 'A hand-gesture fruit-ninja style game with a samurai theme. Swipe your hand to slash targets flying across the screen — but never cut the sacred scrolls.', 'Action', 'single', 1, 1, 'from-red-600 via-rose-600 to-pink-600', '#dc2626', 4.5, 2025, 8, true, '2026-06-23T19:08:12.947387+00:00', '2026-06-25T15:34:14.863182+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '6-8', '', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/203addf7-0c9c-4d02-bf38-3b5f74b6caf5.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('target-master', 'Target Master', 'Draw the bow. Hit your mark.', 'Gesture-controlled archery where you aim and release with hand movements. Progress through increasingly tricky targets and become the ultimate marksman.', 'Sports', 'single', 1, 1, 'from-amber-500 via-orange-500 to-red-500', '#f59e0b', 4.3, 2025, 10, false, '2026-06-23T19:08:12.947387+00:00', '2026-06-25T15:41:04.04957+00:00', NULL, '311e4601-0ad4-41e9-9615-3521ed8df85b', 'published', 'medium', '6-8', '', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/0f8569a4-1cbf-4c19-9a2f-f14478de473d.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('word-adventure', 'Word Adventure', 'Seek the words, explore the world.', 'A hand-tracking word-search adventure. Pinch-drag to highlight hidden words across themed grids and unlock new levels as your vocabulary grows.', 'Puzzle', 'single', 1, 1, 'from-green-500 via-emerald-600 to-teal-600', '#22c55e', 4.4, 2025, 12, false, '2026-06-23T19:08:12.947387+00:00', '2026-06-25T15:42:19.02212+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '6-8', '', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/46242800-83b9-4402-b9b4-f64cd3021cee.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-pop', 'Gesture Pop', 'Pop glowing orbs with your hands!', 'Use hand tracking to aim and pinch clusters of 3 or more matching orbs to pop them. Chain combos, trigger special orbs, and rack up the highest score before time runs out.', 'Arcade', 'single', 1, 1, 'from-violet-600 to-fuchsia-500', 'violet', 4.5, 2025, 2, false, '2026-06-23T17:00:05.352582+00:00', '2026-06-25T16:02:39.892014+00:00', NULL, 'edaedab4-f74d-44b7-9569-33d388ea0a66', 'published', 'easy', '6-8', 'Pop matching orb clusters with hand gestures before the timer runs out.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/ebd5bfe4-c71f-49d2-bf68-fcb571fddf7e.png', 7, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('whack-a-mole-hand', 'Whack a Mole', 'Whack the moles before they hide!', 'The classic whack-a-mole game, played with real hand gestures! Smash your hand down on the moles as they pop up — fast reflexes win!', 'Action', 'single', 1, 1, 'from-brown-500 to-amber-600', '#d97706', 4.6, 2025, 8, true, '2026-06-23T13:38:42.118483+00:00', '2026-06-25T16:06:20.057685+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'easy', '3-5', 'Whack moles using real hand gestures.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/75990a15-c25e-4925-8579-87681c0e4d2c.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-dash-v2', 'Gesture Dash', 'Jump, slide and dash — hands-free!', 'A fast-paced endless runner where your hand gestures control every move. Jump over obstacles, slide under barriers, and dash through levels.', 'Action', 'single', 1, 1, 'from-amber-500 to-orange-500', '#f59e0b', 4.4, 2025, 10, false, '2026-06-23T13:38:42.118483+00:00', '2026-06-25T16:41:53.83359+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '9-12', 'Hand gesture endless runner game.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/32575181-cf69-4d96-827c-537dc422de74.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-racer-v4', 'Gesture Racer', 'Steer with your hands, race to win!', 'Tilt and steer a racing car using hand gestures detected by your camera. Dodge obstacles and hit top speed on every track.', 'Sports', 'single', 1, 1, 'from-green-600 to-lime-500', '#16a34a', 4.3, 2025, 10, false, '2026-06-23T13:38:42.118483+00:00', '2026-06-25T16:44:25.339921+00:00', NULL, '311e4601-0ad4-41e9-9615-3521ed8df85b', 'published', 'medium', '9-12', 'Hand gesture car racing game.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/eab7d3e5-ace5-4d64-aca7-56202de702fd.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('hand-snake-pro', 'Hand Snake Pro', 'Guide the snake with your bare hands!', 'Control the classic Snake game using hand gesture detection. Grow your snake by eating food without hitting the walls or yourself.', 'Arcade', 'single', 1, 1, 'from-green-500 to-teal-400', '#22c55e', 4.2, 2025, 10, false, '2026-06-23T13:38:42.118483+00:00', '2026-06-25T16:48:41.302102+00:00', NULL, 'edaedab4-f74d-44b7-9569-33d388ea0a66', 'published', 'easy', '6-8', 'Classic Snake controlled by hand gestures.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/7e9ba189-8cd7-4bcf-a957-2d7d6f6892b2.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('penalty-shooter', 'Penalty Shooter', 'Score the perfect penalty kick!', 'Step up to the spot and use hand gestures to aim and shoot a penalty kick. The goalkeeper dives — can you send it into the net?', 'Sports', 'single', 1, 1, 'from-green-700 to-emerald-600', '#15803d', 4.5, 2025, 8, false, '2026-06-23T13:38:42.118483+00:00', '2026-06-25T16:55:54.270328+00:00', NULL, '311e4601-0ad4-41e9-9615-3521ed8df85b', 'published', 'easy', '6-8', 'Shoot penalty kicks with gesture controls.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/68fac57f-4a3d-4edf-b8f1-ff6fa47c2970.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('wizard-academy', 'Wizard Academy', 'Cast spells with magical hand gestures!', 'Enroll in Wizard Academy and learn to cast spells by making the correct hand gestures. Solve puzzles and defeat magical creatures with your powers.', 'Adventure', 'single', 1, 1, 'from-violet-700 to-purple-600', '#6d28d9', 4.5, 2025, 15, false, '2026-06-23T13:38:42.118483+00:00', '2026-06-25T17:03:03.334131+00:00', NULL, '85e61bd0-7140-4540-bdaf-b5e6ed2e6b63', 'published', 'medium', '6-8', 'Cast spells using hand gesture magic.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/a102fbd7-a85f-4996-9338-dfac88940143.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-volleyball', 'Gesture Volleyball', 'Smash and block a volleyball with your bare hands.', 'Gesture Volleyball puts you on a sandy beach court facing a fast-reacting AI opponent. Your camera becomes the controller: move your hands left and right to slide your player across your half of the court, raise one hand high to unleash a powerful smash that rockets the ball deep into the AI side, or spread both hands wide to trigger a blocking stance that deflects incoming shots back over the net. The AI adapts to difficulty — Easy occasionally misses and moves slowly, Normal keeps you honest with moderate smashes, and Hard tracks every ball and fires aggressive slams. First player to reach 7 points wins the match. All menus are navigated by hovering your hand and dwelling — no mouse or keyboard required. Scores are saved to the leaderboard on match end.', 'Sports', 'single', 1, 1, 'from-sky-500 via-blue-600 to-indigo-700', '#38bdf8', 4.5, 2026, 10, true, '2026-06-25T16:56:21.507131+00:00', '2026-06-25T17:07:08.712227+00:00', NULL, '311e4601-0ad4-41e9-9615-3521ed8df85b', 'published', 'medium', '13+', 'Two-hand gesture volleyball — raise to smash, spread to block, first to 7 wins.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/95f37b2e-f1b6-4767-aff7-6d82c29ed650.png', 3, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('dino-runner', 'Dino Runner', 'Jump and duck your way past every obstacle!', 'A gesture-controlled endless runner where you control a dinosaur using your body movements. Jump over cacti and duck under pterodactyls — the further you go, the faster it gets.', 'Action', 'single', 1, 1, 'from-green-600 via-emerald-500 to-teal-600', '#10b981', 4.5, 2025, 10, true, '2026-06-22T14:22:31.199982+00:00', '2026-07-01T12:16:02.893458+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'easy', '6-8', 'Gesture-powered endless runner. Jump and duck with your body!', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/a8fd421b-aecc-4a49-bc69-4877d9c4630c.png', 17, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-snake-arena', 'Gesture Snake Arena', 'Grow. Hunt. Survive.', 'Control a colorful snake using only your hand movements in this gesture-powered arena battle! Steer with your hand, speed up by moving further from center, and make a fist to boost. Collect glowing energy orbs to grow longer, trap AI opponents to destroy them and absorb their energy. 20 intelligent AI snakes with unique behaviors, 6 power-ups, combo system, quest missions, cosmetic unlocks, and 8 themed environments keep every session fresh. How long can you survive as the largest snake in the arena?', 'Action', 'single', 1, 1, 'linear-gradient(135deg, #1a3a1a 0%, #5EED7A 50%, #00F5FF 100%)', '#5EED7A', 4.8, 2026, 15, false, '2026-06-30T12:57:18.594976+00:00', '2026-07-02T11:19:35.693761+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '6-8', 'Gesture-controlled snake arena — grow, trap opponents, and dominate!', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/ae8c08f1-58d9-4dbe-8950-6abb515a7726.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('flag-quest', 'Flag Quest: World Colors', 'Paint the world''s flags using nothing but your hand — no mouse, no keyboard, no touch.', 'Flag Quest: World Colors is a fully gesture-controlled painting quest across a hand-built atlas of national flags. Every level shows an outlined flag with its colored regions missing — hover your fingertip over a paint swatch for half a second to select a color, then hold your finger inside the matching region to fill it in with a satisfying gradual wash of color, sparkles, and a soft chime. Pick the wrong region and it flashes red and fades instead of punishing you harshly. Chain correct fills without a mistake to build combo multipliers up to x10, race a per-flag target time for bronze through perfect medals, and earn up to three stars per country. World Tour unlocks continents and countries progressively as you collect stars, Practice mode offers unlimited time with hints on any unlocked flag, and Endless mode serves up a randomized, gradually harder stream of flags for a leaderboard run. A built-in Gallery tracks capitals, population, language, independence year and a fun fact for every flag you unlock. Every menu is operated purely by hovering a fingertip over a glowing button for about 700ms, including fully gesture-driven sliders and toggles. An open palm pauses the game and a fist resumes it, matching the pause gesture used across KinetoFun.', 'Puzzle', 'single', 1, 1, 'from-slate-950 via-indigo-900 to-fuchsia-950', '#8C5CFF', 4.8, 2026, 12, true, '2026-07-01T14:43:09.718529+00:00', '2026-07-02T11:15:18.373961+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '6-8', 'Gesture-only flag painting: hover to pick a color, hold your finger in the outline to fill it in, race the clock for stars.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/8dadbcd7-8a27-436c-94f9-b09580bc106d.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('maze-muncher', 'Maze Muncher: Gesture Edition', 'Steer through a neon maze with nothing but your hand — no mouse, no keyboard.', 'Maze Muncher: Gesture Edition is a fully gesture-controlled maze-chase game — every menu, gesture-driven; every move, made with your hand. Move your hand into an up/down/left/right zone around center to steer through a glowing neon maze, munching energy orbs while four original AI hunters give chase: the Chaser Drone paths straight at you, the Ambush Bot predicts where you are headed and cuts you off, the Patrol Sentinel walks a fixed loop, and the Rogue Hunter is gloriously unpredictable. Grab a power orb and the tables turn for 8 seconds — hunters flash and flee, and you can defeat them for a big combo bonus. Rare gems and treasures flicker into existence for a few seconds at a time, and a classic warp tunnel lets you cut across the arena. Ten procedurally sculpted neon sectors ramp up in enemy count, speed and aggression as you climb the levels. Every menu — Start, Settings, Pause, Game Over — is operated by hovering your hand over a button for a second, or by holding a simple pose: open palm to pause, a fist to resume, thumbs up to confirm, a victory sign to restart. Built for TVs and projectors with a full accessibility suite: high contrast, colorblind-friendly palette, large UI text, adjustable gesture sensitivity and smoothing, and one-tap camera calibration.', 'Action', 'single', 1, 1, 'from-slate-950 via-emerald-900 to-cyan-950', '#39ff88', 4.7, 2026, 14, true, '2026-07-01T13:29:30.948595+00:00', '2026-07-02T11:17:09.019312+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '3-5', 'Gesture-only neon maze chase: steer with your hand, dodge 4 AI hunters, power up to turn the tables.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/a315ab12-b5ee-48cc-af53-8838e41dd278.png', 2, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-table-tennis', 'Gesture Table Tennis Arena', 'Your hand IS the paddle.', 'Step up to the table and play real-time table tennis using only your hand! Move your hand left and right to position the paddle, raise or lower it to control height, rotate your wrist for topspin and backspin, and swing fast for powerful smashes. Battle six unique AI opponents across eight stunning arenas, each with their own playstyle. Challenge yourself with six game modes — Classic Match, Arcade Challenge with crazy modifiers, Survival Mode for endless rallies, Precision Shot for target hunting, Smash Challenge for one-minute power fests, and a full Tournament bracket. Unlock 10 paddle skins, 6 ball skins, and 7 trail effects with coins earned from epic rallies. Features real 3D ball physics with spin, bounce, and net interactions projected to a stunning perspective view.', 'Sports', 'single', 1, 1, 'linear-gradient(135deg, #0a0014 0%, #7c3aed 50%, #22d3ee 100%)', '#a855f7', 4.9, 2026, 10, false, '2026-06-30T13:35:47.430065+00:00', '2026-07-02T11:18:51.734742+00:00', NULL, '311e4601-0ad4-41e9-9615-3521ed8df85b', 'published', 'medium', '9-12', 'Gesture-controlled table tennis — move your hand, swing fast, and smash!', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/dfd576ca-58f3-4060-b0de-a87f4ef17a16.png', 10, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('kingdom-clash', 'Kingdom Clash', '', 'Hand-tracked castle-defense strategy. Pinch and drag unit cards — Knight, Archer, Mage, Giant — onto your half of the battlefield. Spend mana wisely to destroy the enemy castle before yours falls. 10 escalating levels.', 'Adventure', 'single', 1, 1, 'from-yellow-900 via-amber-900 to-stone-950', '#c0a855', 0, 2026, 0, false, '2026-06-29T16:47:48.411719+00:00', '2026-07-02T11:23:44.711759+00:00', NULL, '85e61bd0-7140-4540-bdaf-b5e6ed2e6b63', 'published', 'medium', '13+', '', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/39bda32b-aa36-4c9a-ba9a-d0c0c0e9a9e8.png', 5, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('dance-freeze', 'Dance Freeze', 'Dance when the music plays — freeze the instant it stops!', 'Dance Freeze is a high-energy gesture party game. Dance freely while the beat plays, then hold perfectly still the moment the music cuts. The camera tracks your movement in real time — any detectable motion while frozen means you are out! Survive multiple elimination rounds, strike the silliest frozen poses, and outlast your personal best. Perfect for a quick energy burst or a classroom warm-up.', 'Party', 'single', 1, 1, 'from-pink-500 via-fuchsia-500 to-purple-600', '#ec4899', 4.4, 2026, 8, false, '2026-06-26T16:51:31.940975+00:00', '2026-07-02T11:30:50.386073+00:00', NULL, 'e185b9c2-318b-4d72-9a24-7892a9890d7a', 'published', 'easy', '3-5', 'Groove to the music and snap into a statue on cue — any movement when frozen knocks you out!', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/c97ee646-cf32-44fa-a54f-1369c48c46f0.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('funny-face-contest', 'Funny Face Contest', 'Pull the most ridiculous face you can — the AI will judge!', 'Funny Face Contest uses MediaPipe face and hand tracking to score your silliest expressions in real time. On-screen prompts ask you to raise your eyebrows, stick out your tongue, puff your cheeks, or wink — the more exaggerated, the higher your score. Collect points across timed rounds, unlock wilder challenges, and compete for the ultimate Silly Face crown. Guaranteed to produce genuine laughter.', 'Party', 'single', 1, 1, 'from-yellow-400 via-orange-400 to-pink-500', '#fbbf24', 4.2, 2026, 7, false, '2026-06-26T16:51:31.940975+00:00', '2026-07-02T11:32:09.099132+00:00', NULL, 'e185b9c2-318b-4d72-9a24-7892a9890d7a', 'published', 'easy', '3-5', 'Strike outrageous expressions on command and let the gesture AI score your silliness.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/06fa83f3-ee14-4f05-b510-9e7a29dc16c9.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-chef', 'Gesture Chef', 'Cook up a storm using nothing but your hands!', 'Gesture Chef puts you in control of a virtual kitchen using hand gestures. Wave to chop, swipe to stir, and raise your hand to flip — follow on-screen recipes, manage timers, and plate every dish before the clock runs out. All controls are fully gesture-based; no mouse or keyboard required. Progress through increasingly complex recipes and earn chef stars for speed and precision.', 'Action', 'single', 1, 1, 'from-orange-400 via-yellow-500 to-red-400', '#f97316', 4.3, 2026, 10, false, '2026-06-26T16:51:31.940975+00:00', '2026-07-02T11:33:07.789838+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'easy', '6-8', 'Cook virtual dishes with hand gestures — chop, stir, and plate your way to culinary stardom.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/d70e0dc7-aa4d-4ef2-aa93-97db43ca1f0e.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-ludo-king', 'Gesture Ludo King', 'The classic board game — played entirely with hand gestures.', 'Gesture Ludo King brings the beloved Ludo board game to life with full gesture controls. Wave your open hand to roll the dice, point to select a token, and swipe in the direction of travel to move it. Play against up to three AI opponents across beginner, medium, and expert difficulty levels. Classic Ludo rules apply — race your four tokens from start to home while sending rival tokens back to base. No touching required; pure gesture-based strategy fun.', 'Puzzle', 'single', 1, 1, 'from-blue-600 via-indigo-600 to-violet-700', '#6366f1', 4.3, 2026, 20, false, '2026-06-26T16:51:31.940975+00:00', '2026-07-02T11:33:51.913624+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '9-12', 'Play Ludo with hand gestures — wave to roll dice, point and swipe to move your tokens.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/729f0da2-9801-4170-b2d7-ca35e46e658c.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('magic-cleaning', 'Magic Cleaning', 'Sweep, scrub, and sparkle — all with a wave of your hand!', 'Magic Cleaning is a satisfying gesture-based tidying game. Use sweeping arm motions to brush away dust, scrubbing gestures to polish stains, and pinching moves to pick up clutter and drop it in the right bins. Each level presents a messier room than the last, and a countdown timer keeps the pressure on. Earn a perfect clean rating by removing every speck before time runs out — then watch the room sparkle back to life.', 'Action', 'single', 1, 1, 'from-cyan-400 via-teal-500 to-emerald-600', '#14b8a6', 4.1, 2026, 8, false, '2026-06-26T16:51:31.940975+00:00', '2026-07-02T11:34:29.992696+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'easy', '6-8', 'Sweep and scrub messy rooms back to perfection using magical hand gesture cleaning powers.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/8c2c2cb1-f317-4bbc-a6b0-c0c24100773e.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('rock-paper-scissors', 'Rock Paper Scissors', 'The classic hand game — now played with real hand gestures detected live.', 'Rock Paper Scissors uses MediaPipe hand tracking to read your actual hand shape in real time. Make a tight fist for Rock, flatten your hand for Paper, or extend two fingers for Scissors — the camera sees your gesture instantly. Go head-to-head against a reactive AI opponent across best-of-5, best-of-7, or best-of-9 rounds. The AI ramps up its reaction speed as your win streak grows. No buttons, no delays — just raw hand-vs-AI gesture action.', 'Arcade', 'single', 1, 1, 'from-slate-500 via-gray-600 to-zinc-700', '#64748b', 4.5, 2026, 5, false, '2026-06-26T16:51:31.940975+00:00', '2026-07-02T11:35:11.866243+00:00', NULL, 'edaedab4-f74d-44b7-9569-33d388ea0a66', 'published', 'easy', '6-8', 'Throw a real fist, flat hand, or scissors and let the gesture AI determine who wins.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/c019d392-9616-4330-82b0-293ae214fc7d.png', 0, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('opposites-match', 'Opposites Match', 'Point at the opposite word or picture — big & small, hot & cold, fast & slow.', 'Opposites Match is a gesture-only vocabulary-building game that teaches kids opposite word pairs, built on the same proven hover-select platform as Weather & Seasons Sorter and Coin & Money Counter. Each round shows one word from an opposite pair — as text or as a small icon — and the player hovers a fingertip over the matching opposite among a few choices (~600ms dwell) to score. Three modes vary the presentation: Words (text prompt, text answers), Pictures (icon prompt, icon answers), and Mixed (randomly varies presentation each round). Twelve opposite pairs (big/small, hot/cold, fast/slow, up/down, happy/sad, day/night, open/closed, full/empty, tall/short, wet/dry, loud/quiet, heavy/light), each with a simple hand-drawn icon per side. Since "opposite of" is a symmetric relation, which word of the pair is shown as the prompt is randomized every round, so kids practice both directions (big→small and small→big) across a session. Distractor answers are always drawn from other pairs entirely, so a wrong choice is never a near-miss synonym. Optional spoken narration asks the question and confirms the answer ("The opposite of Big is Small!"). Same no-penalty philosophy as every other KinetoFun gesture game: wrong answers just wobble with a soft tone, no score deduction, no fail state, every session earns at least one star. 6 achievements (First Round, Word Master, Picture Master, Mixed Master, Perfect Round, Opposite Genius). Reuses the same proven gesture stack as the sibling games — single shared MediaPipe HandLandmarker session, hover-dwell selection, Web Audio synthesis + Web Speech narration, Zustand persisted local save. No per-game scores table needed — same generic `public.scores` wiring as every other game.', 'Puzzle', 'single', 1, 1, 'from-orange-950 via-amber-900 to-emerald-950', '#F07A26', 4.7, 2026, 6, true, '2026-07-02T13:17:02.058049+00:00', '2026-07-02T13:27:08.855264+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'easy', '3-5', 'Gesture-only vocabulary game: point at the opposite word or picture — no fail state, ever.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/7f49fe25-c0df-4357-94a2-a5b7667b0ab9.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('world-explorer', 'World Explorer', 'Travel the globe — how well do you know the world?', 'A gesture-powered geography quiz that takes you on a trip around the world. Answer questions about countries, capitals, landmarks and cultures. Use hand gestures to select your answer.', 'Adventure', 'single', 1, 1, 'from-teal-500 via-cyan-600 to-blue-600', '#14b8a6', 4.5, 2025, 15, false, '2026-06-22T14:22:31.199982+00:00', '2026-06-26T13:36:05.930226+00:00', NULL, '85e61bd0-7140-4540-bdaf-b5e6ed2e6b63', 'published', 'medium', '13+', 'Gesture-controlled geography quiz. Explore countries and capitals!', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/f92c7029-587f-466c-8bdf-f58a6c5c0384.png', 5, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-basketball', 'Gesture Basketball', 'Arc perfect free throws with your bare hands.', 'Gesture Basketball puts you on the free-throw line with a real basketball hoop to aim for. Your camera becomes the controller: move your hand left and right to adjust your arc angle (wrist X position maps directly to launch angle, with the center position giving a perfect 55-degree trajectory). Watch the oscillating power meter on the left — it swings between weak and strong continuously. Raise your hand sharply above your head to release the shot at whatever power value the meter is showing at that moment. Time your raise to hit the green sweet-zone on the meter for the ideal arc. You get 10 free throw attempts per game; each basket scores 10 points for a maximum of 100. The ball can also bounce off the backboard for a classic bank shot. Three difficulty levels change how forgiving the rim is and how fast the power meter oscillates: Easy (50px scoring zone, 4-second period), Normal (33px zone, 2.6-second period), Hard (18px zone, 1.8-second period — precision only). All menus are navigated by hand-dwell — no keyboard required. Final score is saved to the leaderboard on game end.', 'Sports', 'single', 1, 1, 'from-orange-500 via-red-600 to-orange-800', '#fb923c', 4.6, 2026, 8, true, '2026-06-26T12:47:21.927947+00:00', '2026-06-26T13:26:12.841283+00:00', NULL, '311e4601-0ad4-41e9-9615-3521ed8df85b', 'published', 'medium', '13+', 'Raise your hand to shoot free throws — aim with wrist X, time the power meter.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/d73392e0-e7f2-4fb5-aa79-035ca200dc21.png', 9, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-sudoku', 'Gesture Sudoku', 'Hover a cell and pinch to select it, then hover a number to fill it in — a classic number puzzle, gesture-only.', 'Gesture Sudoku brings the platform''s first number-logic puzzle, built entirely from gesture primitives already proven in this catalog rather than any new gesture-detection code: hovering a cell and pinching down selects it (the same hover-then-pinch tap used by Word Search''s grid), and hovering one of the nine number buttons (or Erase) for a moment fills the selected cell (the same hover-dwell used by every menu and HUD control on the platform). A held pinch never needs to drag anywhere — Sudoku has no path to trace, just a tap to select and a dwell to fill — which keeps the interaction unusually simple to both build and play. Puzzles are generated fresh each round with a randomized backtracking solver (a real, valid 9x9 solution every time) and then reduced to a difficulty-appropriate number of starting clues (Easy 40, Medium 32, Hard 26). Conflicting entries (a repeated digit in a row, column, or 3x3 box) highlight immediately but never penalize — matching the platform''s established no-punishment philosophy — and a single-cell Hint reveals just the correct digit for whichever cell is selected, never the rest of the board. Four modes: Classic (an untimed single puzzle), Timed (a 5-minute countdown), Zen (fully relaxed, no clock), and Daily (a seeded puzzle shared by everyone that day, generated identically for every player via the same seeded-random convention as the platform''s other Daily modes). A two-hands-raised gesture restarts the puzzle at any point. Web Audio synthesis covers cell selection, digit entry, erase, a conflict buzz, and a victory fanfare; puzzles completed, best scores per mode+difficulty, and daily completion persist to localStorage.', 'Puzzle', 'single', 1, 1, 'from-sky-950 via-slate-900 to-blue-950', '#38BDF8', 4.7, 2026, 10, false, '2026-07-06T18:03:29.209117+00:00', '2026-07-07T10:25:12.681191+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '13+', 'A gesture-only Sudoku: hover and pinch to pick a cell, hover a number to fill it in.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/df80c22c-618a-48f2-a7b5-2b0e7c400fe4.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('connect-2-balls', 'Connect 2 Balls', '', 'Draw paths to connect matching coloured balls and fill the entire grid. 30 hand-crafted campaign levels, endless and daily challenage modes. Gesture-controlled — pinch to select, swipe to navigate.', 'Puzzle', 'single', 1, 1, 'from-indigo-900 via-purple-900 to-pink-900', '#a855f7', 0, 2026, 0, false, '2026-06-29T16:48:10.020012+00:00', '2026-07-02T11:22:08.033627+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'easy', '9-12', '', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/a215c780-2d6d-45d1-b16c-24570861cda8.png', 9, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('the-sniper-code', 'The Sniper Code', 'A gesture-only marksman game — aim, wait, and take the perfect shot.', 'The Sniper Code is a gesture-controlled sniper game played entirely with your hand — no keyboard, mouse, or controller. Look down a realistic scope and pan across the scene by moving your hand; the crosshair stays centred while the world drifts beneath it. Pinch your thumb and index finger together to fire, hold an open palm to cycle 2x / 4x / 8x zoom, and keep your hand perfectly still to engage STEADY AIM for less sway and bonus points. Each mission gives you a clear objective: eliminate the suspect marked with a red diamond, protect a VIP from an approaching attacker, stop a runner before they escape, lead a moving target, or pick the right suspect out of a busy crowd — all while sparing every civilian. A 14-mission campaign ramps up with farther targets, night, fog, crosswind, decoys, tighter timers and limited ammo across six hand-drawn environments (downtown, park, harbor, station, construction site and night rooftops). Hit-zones reward precision: headshots score double, clean streaks build a combo multiplier up to 5x, and every mission is rated up to three stars. An Endless mode delivers escalating waves for score-attack runs. Family-friendly, stylized, gore-free hit effects throughout. Progress, stars, settings and best scores are saved locally. All menus are gesture-driven — hover your hand over a button for one second to select it.', 'Action', 'single', 1, 1, 'from-slate-900 via-red-900 to-slate-950', '#dc2626', 4.7, 2026, 12, true, '2026-06-29T11:38:20.976153+00:00', '2026-07-02T11:29:27.859841+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '13+', 'Gesture-only sniper: aim with your hand, pinch to fire, palm to zoom. 14 missions + Endless.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/d62ab01d-2de1-4ad8-bae4-1788b1e0ddf2.png', 10, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('alphabet-zoo', 'Alphabet Zoo', 'Point at the right letter to learn ABCs — perfect for toddlers.', 'Alphabet Zoo is a toddler-friendly letter-recognition and early-phonics game, built on the same gentle gesture-only platform as Shape & Color Sorter. A single letter glyph or animal emoji bobs center-stage — hover a fingertip over the matching letter button (~600ms dwell) to sort it in, with a cheerful chime and optional spoken narration. Three simple modes teach different skills — Letter Match (bare letter glyphs for shape recognition), Animal Sounds (emoji + word to teach the letter-to-sound link, like "L is for Lion"), and Mixed (random pick of which presentation to use each round). Same no-penalty philosophy as Shape & Color Sorter: wrong letters just wobble + soft tone, no penalty, no fail state, every 10-round session still earns ≥1 star. Bin count ramps 2→3→4. Standalone settings (gesture-only volume sliders + toggles for colorblind icons, high contrast, larger cursor, slower pace, spoken narration). Shortened 2-step calibration. 7 achievements (First Round, Letter Master, Animal Master, Mixed Master, Perfect Round, Little Scholar [10 sessions], A to Z [seen all 26 letters across all sessions]). Reuses the battle-tested gesture stack from Flag Quest and Shape & Color Sorter — single shared MediaPipe HandLandmarker session driving both hover-to-select menus and 60fps in-game dwell, the proven dwell-progress pattern, the Web Audio synthesis idiom, and Zustand persist stores for local save. No per-game scores table needed — same generic `public.scores` wiring.', 'Puzzle', 'single', 1, 1, 'from-indigo-950 via-purple-900 to-fuchsia-950', '#F4C430', 4.8, 2026, 5, true, '2026-07-01T15:33:01.210241+00:00', '2026-07-02T11:13:25.7612+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'easy', '3-5', 'Gesture-only ABC learning for little hands: point at letters to learn them by sight and sound — no fail state, ever.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/4004e1bd-fcd3-4074-8ece-6872a474d4cd.png', 2, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('shape-color-sorter', 'Shape & Color Sorter', 'Point at the right basket to sort every shape and color — perfect for the youngest players.', 'Shape & Color Sorter is a gentle, gesture-only sorting game built for the youngest KinetoFun players. A friendly shape bobs in the center of the screen — hover a fingertip over the matching basket for about half a second to sort it in, with a cheerful chime, a burst of sparkles, and (optionally) the shape or color name spoken aloud. There is no timer, no fail state, and no harsh punishment: choosing the wrong basket just gives it a gentle wobble and a soft "try again" tone, then waits patiently for another try. Three simple modes build different skills — Sort by Shape (circle, square, triangle, star, heart, diamond), Sort by Color (red, blue, green, yellow, orange, purple), and Mixed Mode, which asks for both together. Basket count grows gently from two to four across each 12-round session, and a shortened two-step calibration ("show me your hand", "point at the star") gets even the youngest players started in seconds. Every menu — Sort by Shape, Sort by Color, Mixed Mode, Settings, Exit — is operated purely by hovering a fingertip over a glowing button, including gesture-driven volume sliders and toggles for colorblind-safe icons, high contrast, a larger cursor, a slower pace, and spoken narration. Stars and simple achievements (First Sort, Shape Master, Color Master, Mixed Master, Perfect Round, Super Sorter) are saved automatically so progress carries between sessions.', 'Puzzle', 'single', 1, 1, 'from-indigo-950 via-purple-900 to-fuchsia-950', '#9B4FD6', 4.7, 2026, 8, true, '2026-07-01T15:15:05.529188+00:00', '2026-07-02T11:14:23.472611+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'easy', '3-5', 'Gesture-only sorting game for little hands: hover the matching basket to sort shapes and colors — no fail state, ever.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/69e9b58f-c4dc-44c8-81cc-5443a48ab3a9.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('memory-match-zoo', 'Memory Match Zoo', 'Flip cards to find matching animal pairs — a classic memory game played by pointing.', 'Memory Match Zoo is a gesture-only card-flip concentration game, the fourth game in the small-and-simple KinetoFun family and the first built on a genuinely new mechanic rather than a re-skin of the point-and-sort pattern. A grid of face-down cards hides pairs of zoo animals — hover a fingertip over a card (~600ms dwell) to flip it, then flip a second card. Matching pairs lock face-up with a cheerful chime; a mismatch briefly reveals both cards so the player can remember them, then flips them back — no timer, no penalty, no fail state, same house philosophy as every other KinetoFun gesture game. Three board sizes double as difficulty levels: Small Zoo (3 pairs, 6 cards) for the youngest players, Medium Zoo (6 pairs, 12 cards), and Big Zoo (8 pairs, 16 cards) for players who have outgrown the smaller boards. Scoring is based on flip efficiency against the theoretical-minimum flip count, graded generously so every cleared board earns at least one star. Optional spoken narration says each animal''s name aloud on flip. 6 local achievements (First Match, Small/Medium/Big Zoo Master, Perfect Memory, Memory Champion). Reuses the same proven gesture stack as Flag Quest, Shape & Color Sorter, and Alphabet Zoo — single shared MediaPipe HandLandmarker session, hover-dwell selection, Web Audio synthesis + Web Speech narration, Zustand persisted local save. No per-game scores table needed — same generic `public.scores` wiring as every other game.', 'Puzzle', 'single', 1, 1, 'from-indigo-950 via-purple-900 to-fuchsia-950', '#2FA35A', 4.7, 2026, 6, true, '2026-07-01T15:52:28.09525+00:00', '2026-07-02T11:11:43.9571+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'easy', '6-8', 'Gesture-only memory game: flip cards with your fingertip to find matching animal pairs — no fail state, ever.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/eb9271ed-a34d-49f4-b019-80ce145e04f3.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-darts', 'Gesture Darts', 'Aim with your finger, draw back a fist, and open your hand to release — real 301, 501, and Cricket rules against a CPU opponent.', 'Gesture Darts brings the exact aim/draw/release gesture flow this platform''s archery and mini-golf games already use to a real dartboard: the index finger moves the aiming reticle at all times, closing a fist draws back and charges a power meter, and opening the hand releases the dart. The dartboard itself is modeled with regulation proportions (double-bull, bull, triple ring, and double ring computed from real board measurements) so where a dart lands is genuinely determined by aim and throw strength, not a simplified target. Three authentic game modes are supported: 301 and 501 (classic countdown play with real bust rules — going below zero, landing on a score of 1, or reaching zero without the final dart being a double all void the entire turn) and Cricket (closing the 15 through 20 numbers and the bull with three marks each, then scoring extra hits against an opponent who hasn''t closed the same number). A turn-based CPU opponent throws its own three darts every other turn through the identical scoring engine the player uses, with three difficulty tiers controlling only how shaky its simulated aim is — Easy misses its intended target by a wide margin, Hard is a nearly precise thrower. A Daily Challenge seeds the CPU''s throws identically for every player on a given day. A two-hands-raised gesture restarts the match instantly, and every HUD control is a hover-dwell button, matching the platform-wide "no clicks" convention. Web Audio synthesis provides distinct tones for triples, doubles, bullseyes, busts, and match victory/defeat; match results (wins, best score per mode+difficulty, daily completion) persist to localStorage.', 'Sports', 'single', 1, 1, 'from-orange-950 via-stone-900 to-amber-950', '#FB923C', 4.6, 2026, 8, false, '2026-07-07T10:42:28.195609+00:00', '2026-07-07T11:44:53.909623+00:00', NULL, '311e4601-0ad4-41e9-9615-3521ed8df85b', 'published', 'medium', '9-12', 'A gesture-only darts game: aim with your finger, draw a fist, release to throw — real 301/501/Cricket vs a CPU.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/f0566c91-6ab4-4e91-9183-06730c2c5899.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('spear-stickman', 'Spear Stickman', 'Aim with your hand, charge a fist, and hurl spears at waves of stickmen.', 'Spear Stickman is a gesture-controlled arcade survival game played entirely with your hand — no keyboard, mouse, or controller. You are a stickman defender: move your hand to aim, watch the live trajectory arc, then make a fist to charge a powerful throw and open your hand to launch it (or pinch for a fast, lighter throw). Swipe sideways to dodge incoming spears. Aim for the head — headshots defeat almost any enemy instantly and score double. Survive escalating waves of eight enemy types — basic stickmen, fast runners, heavy warriors, archers, shield bearers, jumpers, teleporting ninjas — and face a giant boss every five waves with its own health bar and spear barrages. Chain kills without taking damage to build a combo up to 10x, collect power-ups that fly to you (triple spear, piercing, explosive, slow-motion, shield, rapid throw), and earn coins to unlock ten cosmetic spear skins from wood to rainbow. Battle across six hand-drawn arenas (forest, castle, desert, mountain, volcano and a night village) with four modes: Endless Survival, Time Attack, One Life and Headshots Only. Cartoon-stylized and gore-free. High scores, best wave, coins, unlocks, achievements and settings are saved locally. Every menu is gesture-driven — hover your hand over a button for a second to select it.', 'Action', 'single', 1, 1, 'from-amber-900 via-orange-900 to-stone-950', '#f59e0b', 4.7, 2026, 10, true, '2026-06-29T16:25:33.690281+00:00', '2026-07-02T11:24:36.986163+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '13+', 'Gesture survival: aim with your hand, fist to charge, throw spears at stickman waves. 4 modes, bosses, skins.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/dfc627cc-8848-44c5-9dc3-a0ac0a98fbae.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('liquid-puzzle', 'Liquid Puzzle', 'Point to aim, make a fist to grab a tube, hold to pour — sort every color into its own glass tube.', 'Liquid Puzzle is a gesture-only water-sorting puzzle: point your index finger to move the cursor, close a fist over a tube and hold for half a second to grab it, then hover a second tube and hold a fist again to pour. A pour only succeeds if the destination tube is empty or its top color matches — otherwise the move is rejected with a shake and a soft error tone, never silently ignored. Every level is dealt at random and verified solvable by a real solver before it is ever shown to the player, so no puzzle is ever impossible, no matter how scrambled it looks. Three modes: Levels (hundreds of procedurally generated puzzles, growing from 3 colors/4 tubes up through a dozen colors and far more tubes, unlocking one at a time and graded 1-3 stars on moves, hints, and speed), Endless (an ever-escalating ladder with no ceiling, tracking the highest level ever reached), and Daily Challenge (one board shared by everyone each day, seeded by date). A thumbs-up gesture undoes the last pour instantly — with a full, unlimited undo history — and a victory sign (peace sign) reveals the single next recommended move without ever spoiling the full solution. Holding an open palm continuously for two seconds anywhere on screen opens the pause menu, keeping every meaningful in-game action (grab/pour, undo, hint, pause) on its own distinct, deliberately-held pose so nothing fires by accident. A short calibration flow (find a hand, hold an open palm, sweep left/right/up/down) runs once at startup before the main menu appears. Every tube is rendered as glass with a pouring arc-and-splash animation, glow highlights on the selected and hinted tubes, and a full settings panel (gesture sensitivity, cursor speed, animation quality, music/SFX volume, colorblind symbol overlays, and a left-handed HUD layout) alongside lifetime statistics, all stored in localStorage — no mouse, touch, keyboard, or gamepad is used for gameplay at any point.', 'Puzzle', 'single', 1, 1, 'from-sky-950 via-indigo-950 to-fuchsia-950', '#38BDF8', 4.8, 2026, 10, false, '2026-07-07T12:10:52.124748+00:00', '2026-07-07T12:56:52.634753+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '6-12', 'A gesture-only water-sorting puzzle: point to aim, fist to grab a tube, hold to pour it into another.', NULL, 3, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('word-search-hidden-words', 'Word Search: Hidden Words', 'Hover, trace, and confirm with an open palm to hunt down every hidden word — no mouse, no clicks.', 'Word Search: Hidden Words is a gesture-only word-search puzzle built from the ground up around webcam hand tracking, not adapted from touch or mouse controls. A strict selection state machine (IDLE -> HOVERED -> START_SELECTED -> TRACING -> CONFIRMING -> VALIDATED_SUCCESS/FAIL) governs every selection: hovering a fingertip over a letter for 400-600ms starts a trace, moving across the grid extends the path and locks its direction after the second letter, and an open-palm gesture (or lifting the hand off the grid for one second) confirms the word. A closed fist cancels the current trace. Words hide horizontally, vertically, and diagonally, forwards or backwards, across three difficulty tiers (Easy 8x8 straight-only, Medium 10x10 with diagonals and reversed words, Hard 12x12 with dense overlaps) generated by a deterministic word-placement engine. Four modes: Classic (find everything, no clock), Timed (beat a 3-minute countdown), Zen (fully relaxed, no timer), and Daily Puzzle (one seeded grid shared by everyone each day). Every on-screen control — hint, pause, restart — is itself a hover-dwell button, and a two-hands-raised gesture restarts the level instantly, so nothing in the game ever needs a click. An SVG overlay animates the traced path with a glowing stroke; found words lock in a permanent highlight; incorrect traces fade out with no penalty. Web Audio synthesis handles every sound cue (hover tick, letter select, path connect, word found, fail fade, victory chord) and progress/best-times/hints-used persist to localStorage.', 'Puzzle', 'single', 1, 1, 'from-violet-950 via-slate-900 to-fuchsia-950', '#A78BFA', 4.7, 2026, 8, false, '2026-07-06T12:50:34.946767+00:00', '2026-07-07T10:20:53.624078+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'medium', '9-12', 'A gesture-only word search: hover to start, trace with your hand, open palm to confirm the word.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/c3439967-c779-4db2-b70f-e01f56ee6a29.png', 3, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('catch-the-falling-stars', 'Catch the Falling Stars', 'Reach up and grab the stars!', 'Stars fall from the sky — move your hands to catch as many as you can before they hit the ground. A magical gesture game for all ages.', 'Action', 'single', 1, 1, 'from-indigo-600 to-purple-500', '#6366f1', 4.5, 2025, 8, true, '2026-06-23T13:38:42.118483+00:00', '2026-07-07T13:11:52.370237+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'easy', '3-5', 'Catch falling stars with your hands.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/64d54a5d-7cc0-4394-a62d-40960cf1ccd5.jpg', 3, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-mob-rally', 'Mob Rally', 'Grow Your Crowd. Rally to Victory.', 'Lead a growing crowd of stick-figure runners using nothing but your hand! Steer with your wrist to sweep through multiplier gates, dodge crushing obstacles, crash into rival crowds, topple mini-bosses, and smash the castle at the end of every level. Make a fist to trigger Charge Mode and power through the toughest foes — your army glows, destroys weak obstacles, and defeats enemies faster for a few seconds. Hold an open palm to pause and resume, no controller needed. Procedurally generated levels across four unique worlds (Grassland, Desert, Snow, Volcano) mean no two runs are ever the same, with eight obstacle types, eight gate effects, seven power-ups, two boss archetypes, and unlockable cosmetics — helmets, capes, trails, auras and color themes — to customize your mob. An original crowd runner built from the ground up for camera-based, hands-only play.', 'Action', 'single', 1, 1, 'linear-gradient(135deg, #2a1a3a 0%, #FF6B35 50%, #FFD740 100%)', '#FF6B35', 4.8, 2026, 12, true, '2026-07-02T11:55:09.347863+00:00', '2026-07-02T12:25:24.253013+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '6-8', 'Gesture-controlled crowd runner — grow your mob, dodge obstacles, and smash the castle!', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/3bf8b9ae-b840-4c1f-989d-44045f89e851.png', 3, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('musical-instrument-sounds', 'Musical Instrument Sounds', 'Listen to a sound, then point at the matching instrument — drums, guitar, piano, and more.', 'Musical Instrument Sounds is a gesture-only sound-recognition game and the first KinetoFun game with an audio-first prompt: instead of showing something to look at, each round plays a short synthesized instrument sound (Web Audio, procedurally generated, no audio files) and the player hovers a fingertip over the matching instrument icon + name among a few choices (~600ms dwell) to score. A Replay button lets the child re-trigger the prompt sound as many times as needed. Ten instruments across two families — Percussion (drum, tambourine, xylophone, cymbal, maracas) and Melodic (piano, guitar, flute, violin, trumpet) — each with a distinct procedurally-synthesized timbre (noise bursts with different filtering for percussion; oscillator recipes with different waveforms, envelopes, and vibrato for melodic instruments) and a simple hand-drawn icon. Three modes: Percussion, Melodic, and Mixed (draws from all ten). Distractors are always drawn from the same family as the round''s mode (or the full set in Mixed), so every choice is a plausible, genuinely different instrument. Same no-penalty philosophy as every other KinetoFun gesture game: wrong answers just wobble with a soft tone, no score deduction, no fail state, every session earns at least one star. 6 achievements (First Round, Percussion Master, Melodic Master, Mixed Master, Perfect Round, Music Maestro). Reuses the same proven gesture stack as the sibling games — single shared MediaPipe HandLandmarker session, hover-dwell selection, Web Audio synthesis + Web Speech narration, Zustand persisted local save. No per-game scores table needed — same generic `public.scores` wiring as every other game.', 'Puzzle', 'single', 1, 1, 'from-red-950 via-purple-900 to-blue-950', '#9B4FD6', 4, 2026, 6, true, '2026-07-03T09:53:50.292901+00:00', '2026-07-03T10:35:02.681064+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'easy', '3-5', 'Gesture-only sound-matching game: listen to an instrument and point at the match — no fail state, ever.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/f07a9b70-dcc6-48a2-84b9-36a018c6d9bf.png', 1, 1);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('coin-money-counter', 'Coin & Money Counter', 'Point at the coins or amount to learn money recognition and counting — no fail state, ever.', 'Coin & Money Counter is a gesture-only game that teaches kids to count money and recognize coin values, built on the same proven hover-select platform as Clock & Time Teller and Alphabet Zoo. Each round shows an amount one of two ways — a group of coin icons or a digital total — and the player hovers a fingertip over the matching answer among a few choices (~600ms dwell) to score. Two modes teach the skill from both directions: Count the Coins (see coins, pick the digital amount) and Make the Amount (see a digital price, pick the matching coin group), plus a Mixed mode that quizzes both ways. Coin denominations are limited to the standard US coins kids actually use: penny (1¢), nickel (5¢), dime (10¢), quarter (25¢). Amounts stay under $1 (1¢–99¢), the standard "counting coins" range for young kids, with early rounds restricting to amounts that require just 1–2 coins (easier) before later rounds allow up to 4 coins (harder), mirroring the same gentle difficulty ramp as the sibling games. Each amount is always broken down greedily (as many quarters as possible, then dimes, nickels, pennies) to keep the visual small and deterministic. Optional spoken narration says each amount in words ("twenty-seven cents", not raw digits), using age-appropriate vocabulary. Same no-penalty philosophy as every other KinetoFun gesture game: wrong answers just wobble with a soft tone, no score deduction, no fail state, every session earns at least one star. 6 achievements (First Round, Coin Counter Master, Money Maker Master, Mixed Master, Perfect Round, Money Wizard). Reuses the same proven gesture stack as the sibling games — single shared MediaPipe HandLandmarker session, hover-dwell selection, Web Audio synthesis + Web Speech narration, Zustand persisted local save. No per-game scores table needed — same generic `public.scores` wiring as every other game.', 'Puzzle', 'single', 1, 1, 'from-amber-950 via-yellow-900 to-yellow-800', '#FFD700', 4.8, 2026, 6, true, '2026-07-02T12:51:16.399982+00:00', '2026-07-02T13:24:41.345492+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'easy', '3-5', 'Gesture-only money-counting game: point at coins or amounts to learn money recognition — no fail state, ever.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/25ec3efb-d4eb-4adf-9897-4516b28564b1.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('farm-builder', 'Little Farm Builder', 'Plant seeds, watch them grow, and harvest your own gesture-controlled farm.', 'Little Farm Builder is a gesture-only farming simulation and the eleventh game in the KinetoFun family — the first with a genuinely persistent save state (a farm that keeps growing between visits) and the first to use continuous pinch-and-drag as its core interaction instead of hover-and-dwell. Players pinch-grab a seed from the tray at the bottom of the screen, drag it over an empty plot, and release to plant it (costs coins); crops grow through three visual stages — seed, sprout, ripe — based on real elapsed time, so a planted crop keeps maturing even after the player closes the game and comes back later. Once ripe, the player pinch-grabs the crop directly out of its plot and drags it to the basket to harvest it for coins. Four crops with different pacing and value: Carrot (20s, cheap, always unlocked), Tomato (60s), Corn (3 min), and Pumpkin (8 min, most valuable) — new crop types and additional plots (starting at 4, expandable up to 12) are unlocked by spending coins via simple hover-dwell buttons, giving the farm a visible city-builder-style progression over repeated visits. Discrete actions (unlocking a crop type, buying a new plot, menu navigation) reuse the existing hover-dwell `HoverButton` pattern; only planting and harvesting use the new pinch-drag mechanic, built on a new `isPinching` hand-frame primitive (thumb-to-index-tip distance, debounced ~100ms against landmark jitter — the same fix already proven in gesture-love-balls'' pinch-to-draw mechanic) and a purpose-built `usePinchDrag` hook that hit-tests DOM rects at grab/release time, extending the same rect-based hit-testing idiom `HoverButton` already uses for hover detection. No fail state, no score penalty — coins only ever go up, plots only ever unlock, matching the no-punishment philosophy of every other KinetoFun gesture game. 6 achievements (First Harvest, Green Thumb, Full Table, Land Baron, Century Farmer, Master Grower). Reuses the same proven gesture stack as the sibling games — single shared MediaPipe HandLandmarker session, Web Audio synthesis, Zustand persisted local save (a farm-shaped save instead of a best-score-per-mode save, but the same persist-to-localStorage mechanism). No per-game scores table needed — same generic `public.scores` wiring as every other game, just fed a different number (lifetime coins instead of a round score).', 'Adventure', 'single', 1, 1, 'from-green-950 via-emerald-900 to-lime-950', '#2FA35A', 4.8, 2026, 8, true, '2026-07-03T11:24:12.412294+00:00', '2026-07-03T11:56:46.515744+00:00', NULL, '85e61bd0-7140-4540-bdaf-b5e6ed2e6b63', 'published', 'easy', '6-8', 'Gesture-only farming sim: pinch to plant and harvest, watch your farm grow between visits — no fail state, ever.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/5633969c-5515-4095-843b-fc60fb1aca81.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('zoo-architect', 'Zoo & Aquarium Architect', 'Design habitats, unlock animals, and welcome visitors to your gesture-built zoo.', 'Zoo & Aquarium Architect is a gesture-only creative-building sim and the fourteenth game in the KinetoFun family — the third to reuse the persistent-sim + pinch-drag architecture proven by Little Farm Builder (ADR-045) and Pocket Pal (ADR-046), applied to a new domain: designing zoo habitats rather than managing a farm economy or caring for a single pet. Unlike those two games, placement here is free-form rather than grid-based or single-target — the player pinch-grabs an animal or decoration from the shop tray and drops it anywhere within the active habitat, at any position, building up a custom-designed enclosure over time. Four zones act as the game''s natural level structure, unlocked in order with Tickets: Savanna (the starter zone, unlocked from the start), Arctic, Ocean/Aquarium, and Rainforest — each with its own set of unlockable animal species and decorations (lions, elephants, giraffes and zebras in the savanna; polar bears, penguins, seals and arctic foxes up north; dolphins, whales, sea turtles, clownfish and octopi in the aquarium; tigers, gorillas, parrots, monkeys and sloths in the rainforest canopy). Every placed item contributes an "appeal value" to its zone and to the zoo''s overall appeal score; visitors generate Tickets passively over real wall-clock time based on total appeal — the same timestamp-based accrual pattern proven twice already (persisted lastCollectedAt vs. Date.now(), recomputed on load so Tickets keep accruing even while the game is closed), except uncapped rather than [0,1]-bounded, matching the family''s "currency only ever goes up" rule. A "Collect Tickets" dwell button banks the accrued amount into a spendable balance, mirroring Farm Builder''s harvest action. No fail state whatsoever: nothing decays, nothing can be placed "wrong," and appeal only ever increases as the player builds. Same gesture stack as every other game — single shared MediaPipe HandLandmarker session, hover-dwell for zone-switching/menu navigation/unlocks, pinch-drag (reused verbatim from the proven `usePinchDrag` hook) for the one core creative-placement verb. 6 achievements: First Habitat (first placement), Zoologist (10 items unlocked), Zone Master (fully unlock one zone''s roster), World Traveler (all 4 zones unlocked), Ticket Tycoon (1000 lifetime Tickets), Master Architect (50 total placements). Score submitted on exit is lifetime total Tickets earned (monotonic), same `public.scores` table every other game uses — no per-game schema, no DB changes.', 'Adventure', 'single', 1, 1, 'from-emerald-950 via-teal-950 to-slate-900', '#4AD9A4', 4.8, 2026, 0, true, '2026-07-03T13:31:44.578196+00:00', '2026-07-07T10:19:38.249174+00:00', NULL, '85e61bd0-7140-4540-bdaf-b5e6ed2e6b63', 'published', 'easy', '3-5', 'A creative zoo-building sim — pinch-drag animals and decor anywhere you like, no fail state, ever.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/ad998f8c-551a-44aa-9fc3-439934627694.png', 2, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-archery-range', 'Gesture Archery Range', 'Aim with your finger, draw a fist, and open your hand to loose the arrow — no mouse, no trigger.', 'Gesture Archery Range is a gesture-only target-archery game built around a three-step hand flow that mirrors drawing a real bow: the index finger alone moves the aiming reticle over the target at all times; closing a fist begins drawing the bowstring, charging a power meter the longer it is held; opening the hand releases the arrow at whatever power was reached. Relaxing the fist without ever opening the palm is treated as lowering the bow — the draw is abandoned with no arrow spent, just like letting down a real bow. The shot resolution is skill-based on two axes at once: the reticle position is where the arrow lands with exactly the right amount of power and no wind, but under-drawing makes the shot drop low and over-drawing sends it sailing high, so distance judgment matters as much as aim; medium/hard rounds add lateral wind drift that must be aimed off-center to compensate for, the same way real archers correct for crosswind. Three difficulty tiers change target distance, ring size, and wind strength (Easy: close range, no wind; Medium: mid-range, light wind; Hard: long range, strong gusts and tight rings). Four modes: Classic (a fixed quiver of 8 arrows, no clock), Timed (90 seconds to loose as many arrows as possible), Zen (unhurried practice, no timer), and Daily (a seeded distance/wind combo shared by everyone each day). A two-hands-raised gesture restarts the round instantly. Every HUD control (Pause/Restart/Exit) and every menu button is a hover-dwell control, matching the platform-wide "no clicks" convention — the only gestures that ever touch gameplay itself are the index-finger aim, the fist draw, and the open-palm release. Web Audio synthesis handles the string creak, release twang, thud, bullseye chime, miss, and victory cues; round results (best score per mode+difficulty, lifetime bullseyes, daily completion) persist to localStorage.', 'Sports', 'single', 1, 1, 'from-lime-950 via-slate-900 to-emerald-950', '#A3E635', 4.7, 2026, 7, false, '2026-07-06T13:24:20.962697+00:00', '2026-07-07T10:21:57.276858+00:00', NULL, '311e4601-0ad4-41e9-9615-3521ed8df85b', 'published', 'medium', '9-12', 'A gesture-only archery range: point to aim, fist to draw, open your hand to release the arrow.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/e1a47b92-5499-411e-b462-5059899eedd4.png', 4, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-mario', 'Gesture Mario', 'Run and jump like Mario — with gestures!', 'A Mario-inspired platformer controlled entirely by hand gestures. Jump over enemies, collect coins, and reach the flag using your hands.', 'Action', 'single', 1, 1, 'from-red-600 to-orange-500', '#dc2626', 4.6, 2025, 15, true, '2026-06-23T13:38:42.118483+00:00', '2026-07-07T13:11:39.826128+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'medium', '6-8', 'Gesture-controlled Mario-style platformer.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/ec60fcf5-ee7b-419f-bf6e-6f3ec402b5c9.png', 2, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('clock-time-teller', 'Clock & Time Teller', 'Point at the right time to learn to read the clock — analog and digital, both directions.', 'Clock & Time Teller is a gesture-only game that teaches kids to tell time, built on the same proven hover-select platform as Shape & Color Sorter and Alphabet Zoo. Each round shows a time one of two ways — an analog clock face or a digital readout — and the player hovers a fingertip over the matching answer among a few choices (~600ms dwell) to score. Two modes teach the skill from both directions: Read the Clock (see an analog face, pick the digital time) and Set the Clock (see a digital time, pick the matching analog face), plus a Mixed mode that quizzes both ways. Times are restricted to the quarter-hour increments kids are actually taught with (o''clock, quarter past, half past, quarter to), and early rounds only use the easier o''clock/half-past times before introducing quarter hours later in the session. Optional spoken narration says each time using real time-telling vocabulary ("quarter past three", not just digits). Same no-penalty philosophy as every other KinetoFun gesture game: wrong answers just wobble with a soft tone, no score deduction, no fail state, every session earns at least one star. 6 achievements (First Round, Clock Reader Master, Clock Setter Master, Mixed Master, Perfect Round, Time Traveler). Reuses the same proven gesture stack as the sibling games — single shared MediaPipe HandLandmarker session, hover-dwell selection, Web Audio synthesis + Web Speech narration, Zustand persisted local save. No per-game scores table needed — same generic `public.scores` wiring as every other game.', 'Puzzle', 'single', 1, 1, 'from-indigo-950 via-purple-900 to-fuchsia-950', '#F4C430', 4.7, 2026, 6, true, '2026-07-02T12:31:50.873507+00:00', '2026-07-02T12:38:34.690167+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'easy', '6-8', 'Gesture-only clock-reading game: point at the matching time to learn analog and digital time-telling — no fail state, ever.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/d4faaa15-6e67-4514-b5be-c9194c6eb86d.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('pocket-pal', 'Pocket Pal', 'Nurture your gesture-controlled digital companion — feed, play, pet.', 'Pocket Pal is a gesture-only virtual pet companion game and the twelfth game in the KinetoFun family — the second persistent-state sim after Little Farm Builder (ADR-045), proving the lasting-world infrastructure is viable for multiple game genres. Unlike Farm Builder''s economy-and-expansion focus, Pocket Pal is purely relational: a single companion (fixed emoji-based creature, no species picker in v1) that the player feeds, plays with, and pets, watching it grow through five stages (Baby → Child → Teen → Adult → Elder) based on lifetime care actions, and managing two stats — Hunger and Happiness — that decay over real wall-clock time but never fall below a floor of 40/100, so the pet never "dies" or enters a fail state even if totally neglected for days. Same no-punishment philosophy as every KinetoFun game: wrong actions wobble, not penalize; the pet just looks a little sad and perks back up instantly on re-engagement. Interactions split between pinch-drag (Feed and Play, reusing Farm Builder''s `usePinchDrag` hook verbatim) and hover-dwell (petting the pet sprite, unlocking new foods/toys). Nine unlockable care items split across three food types, three toy types, and three cosmetic accessories (hat, bandana, glasses — pure CSS overlay badges, no new asset pipeline). Every care action earns +1 Heart (uncapped, no cooldown — rewards grind-free play), and Hearts spend on unlocking items (one-time, dwell-based). Score submitted on exit is lifetime total Hearts earned (monotonic like Farm Builder''s coins), preserving the leaderboard shape despite having no discrete rounds. 6 achievements: First Friend, Best Buddy (50 actions), All Grown Up (max stage), Full Closet (all unlocks), Heart of Gold (100 Hearts), Picture Perfect (both stats at 100 simultaneously). Stat decay driven by real elapsed time (persisted timestamp vs. Date.now(), same as Farm Builder''s crop growth math), so the companion keeps evolving between visits even when the game is closed. Reuses the proven gesture stack from all 11 prior games: single shared MediaPipe HandLandmarker session, Web Audio synthesis for feedback tones, Zustand persisted local save. No DB schema changes — same generic `public.scores` table, same localStorage-only client-side persistence pattern.', 'Adventure', 'single', 1, 1, 'from-pink-900 via-purple-900 to-indigo-900', '#FF1493', 4.8, 2026, 0, true, '2026-07-03T11:51:31.201008+00:00', '2026-07-03T12:55:17.926321+00:00', NULL, '85e61bd0-7140-4540-bdaf-b5e6ed2e6b63', 'published', 'easy', '3-5', 'A Tamagotchi-style companion that never dies, only moods shift — gesture-controlled growth, no fail state ever.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/1e600d6b-36fd-46b7-b622-c442e2ab1f6b.jpg', 2, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('cookie-monster-game', 'Cookie Monster', 'Om nom nom — grab those cookies!', 'Help the Cookie Monster catch falling cookies using hand gestures. A fun and silly gesture game inspired by everyone''s favorite blue monster.', 'Action', 'single', 1, 1, 'from-blue-500 to-cyan-400', '#3b82f6', 4.6, 2025, 8, true, '2026-06-23T13:38:42.118483+00:00', '2026-07-07T13:11:21.988469+00:00', NULL, '84bf0acb-625d-4057-a2a1-f3737e22f673', 'published', 'easy', '3-5', 'Catch cookies with gesture controls.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/33bfa432-345e-4196-a908-4e16956da7e5.png', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-bowling-lane', 'Gesture Bowling Lane', 'Aim with your hand, wind up, and swing down through the release line to bowl a full 10-frame game.', 'Gesture Bowling Lane is a gesture-only ten-pin bowling game built around a swing-through motion instead of a click or a hover-dwell trigger. The hand''s live position sets where the ball starts on the lane; raising the hand upward crosses a "backswing" line and locks that starting position in, exactly like a bowler settling their approach; swinging the hand back down through a lower "release line" lets the ball go. Two things are captured at that release instant and nowhere else: how fast the downswing was (power — a quick swing rolls harder and carries further into the pin deck) and how far the hand drifted sideways during the forward swing (curve — a hook to one side, just like imparting spin with a real release). A full official ten-frame scoreboard runs underneath: strikes and spares earn the standard bonus-roll scoring, and the tenth frame correctly grants a fresh rack for bonus balls after a strike or spare, matching real bowling rules exactly (verified against known scoring scenarios including a 300 perfect game). Three difficulty tiers change how forgiving the pin knockdown radius is and how sensitive the ball is to sideways curve (Easy: wide hit radius, gentle curve; Hard: tight pocket, twitchy curve, easy to leave a split). Four modes: Classic (a full untimed 10-frame game), Timed (as many frames as fit in 5 minutes), Zen (relaxed, no clock), and Daily (a subtle seeded lane-oil drift shared by everyone that day, on top of the usual physics). A two-hands-raised gesture restarts the game at any point; every HUD/menu control is hover-dwell only, matching the platform-wide "no clicks" convention — the swing itself is the only motion-based gesture in the game. Web Audio synthesis covers the windup whoosh, release twang, pin crash, gutter thud, strike/spare chimes, and a game-over fanfare; best scores per mode+difficulty, lifetime strikes, and daily completion persist to localStorage.', 'Sports', 'single', 1, 1, 'from-amber-950 via-slate-900 to-orange-950', '#FCD34D', 4.7, 2026, 10, false, '2026-07-06T13:56:56.218394+00:00', '2026-07-07T13:11:52.394719+00:00', NULL, '311e4601-0ad4-41e9-9615-3521ed8df85b', 'published', 'medium', '9-12', 'A gesture-only ten-pin bowling game: aim with your hand, wind up, and swing down to release the ball.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/e7983a62-9273-4938-99cd-24d6693d5121.png', 2, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('fruit-vegetable-sorter', 'Fruit & Vegetable Sorter', 'Look at fresh produce and sort it into the right category — fruits or vegetables!', 'Fruit & Vegetable Sorter is a gesture-only categorization game and the tenth game in the KinetoFun family, teaching early nutrition and food literacy by sorting produce into two main categories: Fruits and Vegetables. Each round shows a colorful emoji picture of a produce item (apple, banana, strawberry, watermelon, orange, grape, carrot, broccoli, lettuce, tomato, bell pepper, corn); the player hovers a fingertip over the "Fruit" or "Vegetable" bin (~600ms dwell) to categorize it correctly. A simple two-choice format makes this game accessible and confidence-building from the start. Three modes split by content family (same grouping shape as Alphabet Zoo, Weather Sorter, and Opposites Match): **Fruits** mode focuses on learning common fruits; **Vegetables** mode focuses on learning common vegetables; **Mixed** mode blends both and tests real categorization skill. Distractors are never needed — each round is simply a binary choice (Fruit or Vegetable?). Ten rounds per session, always the same two bins. Same no-penalty philosophy as every other KinetoFun game: wrong answers wobble gently with a soft tone, no score deduction, no fail state, every session earns at least one star. 6 achievements (First Round, Fruit Expert, Veggie Expert, Mixed Master, Perfect Round, Food Champion). Reuses the same proven gesture stack as the sibling games — single shared MediaPipe HandLandmarker session, hover-dwell selection, Web Audio synthesis, Zustand persisted local save. No per-game scores table needed — same generic `public.scores` wiring as every other game.', 'Puzzle', 'single', 1, 1, 'from-green-950 via-emerald-900 to-lime-950', '#2FA35A', 4.8, 2026, 6, true, '2026-07-03T10:49:31.331128+00:00', '2026-07-03T11:33:53.325855+00:00', NULL, '6851c6cd-6afd-4e03-8cb2-eb3c5eb528a9', 'published', 'easy', '6-8', 'Gesture-only produce categorization: sort fruits from vegetables using just hover-dwell — no fail state, ever.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/5598535e-e7c9-4eab-aa9f-e8d56d544831.jpg', 1, 0);
INSERT INTO public.games (id, title, tagline, description, category, players, min_players, max_players, cover, accent, rating, release_year, duration_minutes, featured, created_at, updated_at, cover_image, category_id, status, difficulty, age_group, short_description, thumbnail, play_count, rating_count) VALUES ('gesture-mini-golf', 'Gesture Mini-Golf', 'Point where you want to putt, wind up, and swing down through the release line to roll the ball across the green.', 'Gesture Mini-Golf is a gesture-only putting game that reuses the same swing vocabulary as Gesture Bowling Lane — raise a hand to cross a backswing line, then swing it back down through a release line to let the ball go, with putt power read from how fast that downswing was. Where it diverges from bowling is what happens next: instead of one lane and a fixed pin-knockdown animation, the ball rolls in real time across a top-down green with actual per-tick physics — walls bounce it, sand traps slow it down hard, slopes constantly nudge it sideways, and water hazards sink it with a one-stroke penalty and a drop back to the tee. The putt''s direction comes from wherever the hand is pointing at the moment the backswing locks in, drawn as a dotted aim line from the ball to the target so the sideways compensation needed around walls and slopes is always visible before the swing. Six hand-built holes increase in obstacle complexity from a plain straight tap-in to a sand-and-water-and-corridor-walls combination hole, scored with a real stroke-play scoreboard (birdie/par/bogey labels, hole-in-one detection). Three difficulty tiers change how many of the six holes are played and how forgiving the cup and putt power are (Easy: 4 holes, wide cup, easy reach; Hard: all 6 holes, tight cup, unforgiving power). Four modes: Classic (a full untimed round), Timed (as many holes as fit in 4 minutes), Zen (no clock), and Daily (a subtle seeded "green speed" shared by everyone that day). A two-hands-raised gesture restarts the round at any point; every HUD/menu control is hover-dwell only, matching the platform-wide "no clicks" convention — the swing is the only motion-based gesture. Web Audio synthesis covers the windup whoosh, putt strike, splash, sand thud, holed chime, and a round-complete fanfare; best scores per mode+difficulty, lifetime holes-in-one, and daily completion persist to localStorage.', 'Sports', 'single', 1, 1, 'from-emerald-950 via-slate-900 to-green-950', '#4ADE80', 4, 2026, 9, false, '2026-07-06T16:50:10.814629+00:00', '2026-07-07T10:24:16.387669+00:00', NULL, '311e4601-0ad4-41e9-9615-3521ed8df85b', 'published', 'medium', '9-12', 'A gesture-only mini-golf game: point to aim, wind up, and swing down to putt across six obstacle-filled holes.', 'https://eyipksddjxhbjfjofktj.supabase.co/storage/v1/object/public/game-covers/993c7a3f-326f-4d52-b66f-d972b1d35f8a.png', 2, 1);
